<?php

require_once __DIR__ . '/config/database.php'; require_once __DIR__.'/config/ui.php';
// Compatibilidad con instalaciones que conservan su configuración MySQL anterior.
require_once __DIR__ . '/config/bbva_pyme.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();

define('LOGO_B64', '');
define('AMW_LOGO_B64', '');

$cotizacion_generada = false;
$cotizacion_id = isset($_GET['id']) ? (int)$_GET['id'] : 0;
$folio = '';
$modo_pdf = isset($_GET['modo_pdf']) && $_GET['modo_pdf'] === '1';
$modo_preview = $modo_pdf && isset($_GET['preview']) && $_GET['preview'] === '1';
$tipo_pdf = $_GET['tipo'] ?? 'factura';
$requiere_factura = 'si';

/* ==========================================================
   VALORES POR DEFECTO
   ========================================================== */

$cliente = '';
$telefono = '';
$cliente_id = 0;
$vehiculo = '';
$fecha_raw = date('Y-m-d');
$fecha = '';
$items = [];

$subtotal = 0;
$iva = 0;
$total_final = 0;

$total_con_factura = 0;
$total_sin_factura = 0;

/* MSI incluidos siempre; se recalculan también al abrir documentos anteriores. */
$msi_plazos_sel = ['3','6','9','12','18','24'];
$bbva_pyme = false;
$tarjeta_una_exhibicion = true;
$anticipo_tipo = 'porcentaje';
$anticipo_valor = 70.00;
$conservar_anticipo_recibido = false;
$anticipo_recibido_monto = 0.00;
$dividir_anticipo = false;
$repartir_igual = false;
$anticipo_sergio = 0.00;
$anticipo_ricardo = 0.00;
$anticipo_tomas = 0.00;
$participa_sergio = true;
$participa_ricardo = true;
$participa_tomas = false;
$estado = 'Cotización';
$vigencia_dias = 15;
$dias_trabajo_general_min = 0;
$dias_trabajo_general_max = 0;
$motivo_version = '';
$guardar_articulos_catalogo = true;
$catalogo_servicios = $modo_pdf ? [] : srnu_catalogo_activo();
$clientes_registrados = $modo_pdf ? [] : srnu_clientes_activos();
$bbva_opciones = [];
$hay_sobre_pedido = false;
$dias_sobre_pedido = 0;


$msi_opciones_factura = [];
$msi_opciones_sin_factura = [];
$msi_no_disponible_factura = [];
$msi_no_disponible_sin_factura = [];
$tarjeta_una_exhibicion_factura = null;
$tarjeta_una_exhibicion_sin_factura = null;

/* Límite máximo para meses sin intereses */
$msi_limite_maximo = 50000.00;

/* Anticipos */
$anticipo_factura['monto'] = 0;
$anticipo_factura['saldo'] = 0;

$anticipo_sin_factura['monto'] = 0;
$anticipo_sin_factura['saldo'] = 0;


/* ==========================================================
   CARGAR COTIZACIÓN EXISTENTE
   ========================================================== */

if ($cotizacion_id > 0 && $_SERVER['REQUEST_METHOD'] !== 'POST') {
    try {
        $guardada = srnu_obtener_cotizacion($cotizacion_id);
        if ($guardada) {
            $folio = $guardada['folio'];
            $cliente = $guardada['cliente'];
            $telefono = $guardada['telefono'];
            $cliente_id = (int)($guardada['cliente_id'] ?? 0);
            $vehiculo = $guardada['vehiculo'];
            $fecha_raw = $guardada['fecha'];
            $requiere_factura = $guardada['requiere_factura'];
            $items = $guardada['items'];
            $msi_plazos_sel = array_map('strval', $guardada['msi_plazos']);
            $bbva_pyme = in_array('bbva_pyme', $msi_plazos_sel, true);
            $tarjeta_una_exhibicion = true;
            $msi_plazos_sel = array_values(array_diff($msi_plazos_sel, ['bbva_pyme', 'tarjeta_1x']));
            $anticipo_tipo = $guardada['anticipo_tipo'] ?? 'porcentaje';
            $anticipo_valor = isset($guardada['anticipo_valor']) ? (float)$guardada['anticipo_valor'] : 70.00;
            $conservar_anticipo_recibido = !empty($guardada['conservar_anticipo_recibido']);
            $anticipo_recibido_monto = isset($guardada['anticipo_recibido_monto']) ? max(0, (float)$guardada['anticipo_recibido_monto']) : 0.00;
            $dividir_anticipo = !empty($guardada['dividir_anticipo']);
            $repartir_igual = !empty($guardada['repartir_igual']);
            $anticipo_sergio = isset($guardada['anticipo_sergio']) ? (float)$guardada['anticipo_sergio'] : 0.00;
            $anticipo_ricardo = isset($guardada['anticipo_ricardo']) ? (float)$guardada['anticipo_ricardo'] : 0.00;
            $anticipo_tomas = isset($guardada['anticipo_tomas']) ? (float)$guardada['anticipo_tomas'] : 0.00;
            $participa_sergio = !isset($guardada['participa_sergio']) || (bool)$guardada['participa_sergio'];
            $participa_ricardo = !isset($guardada['participa_ricardo']) || (bool)$guardada['participa_ricardo'];
            $participa_tomas = isset($guardada['participa_tomas']) ? (bool)$guardada['participa_tomas'] : false;
            $estado = $guardada['estado'] ?? 'Cotización';
            $vigencia_dias = max(1, (int)($guardada['vigencia_dias'] ?? 15));
            $dias_trabajo_general_min = max(0, (int)($guardada['dias_trabajo_general_min'] ?? 0));
            $dias_trabajo_general_max = max(0, (int)($guardada['dias_trabajo_general_max'] ?? 0));

            /* Para cotizaciones antiguas que aún no tenían el estado de anticipo recibido,
               proponemos automáticamente el adelanto de la versión guardada. Primero usamos
               la suma distribuida entre integrantes si existe; de lo contrario reconstruimos
               el anticipo con el subtotal y la configuración original. */
            if (!$conservar_anticipo_recibido && $anticipo_recibido_monto <= 0) {
                $suma_anticipo_guardada = round($anticipo_sergio + $anticipo_ricardo + $anticipo_tomas, 2);
                if ($dividir_anticipo && $suma_anticipo_guardada > 0) {
                    $anticipo_recibido_monto = $suma_anticipo_guardada;
                } else {
                    $subtotal_guardado = max(0, (float)($guardada['subtotal'] ?? 0));
                    if ($anticipo_tipo === 'monto') {
                        $anticipo_recibido_monto = round(max(0, min($subtotal_guardado, $anticipo_valor)), 2);
                    } else {
                        $pct_guardado = max(0, min(100, $anticipo_valor));
                        $anticipo_recibido_monto = round($subtotal_guardado * ($pct_guardado / 100), 2);
                    }
                }
            }
        }
    } catch (Throwable $e) {
        $error_bd = $e->getMessage();
    }
}


/* Recibir una prueba del Cotizador rápido sin haberla guardado en MySQL. */
if ($cotizacion_id === 0 && $_SERVER['REQUEST_METHOD'] !== 'POST' && (($_GET['desde_rapido'] ?? '') === '1') && !empty($_SESSION['srnu_cotizacion_rapida'])) {
    $rapida = $_SESSION['srnu_cotizacion_rapida'];
    unset($_SESSION['srnu_cotizacion_rapida']);
    $vehiculo = trim((string)($rapida['vehiculo'] ?? ''));
    $requiere_factura = (($rapida['requiere_factura'] ?? 'no') === 'si') ? 'si' : 'no';
    $plazos_rapida = is_array($rapida['msi_plazos'] ?? null) ? array_map('strval', $rapida['msi_plazos']) : [];
    $bbva_pyme = in_array('bbva_pyme', $plazos_rapida, true);
    $guardar_articulos_catalogo = !array_key_exists('guardar_articulos_catalogo', $rapida) || !empty($rapida['guardar_articulos_catalogo']);
    $msi_plazos_sel = array_values(array_intersect(['3','6','9','12','18','24'], $plazos_rapida));
    $items = is_array($rapida['items'] ?? null) ? $rapida['items'] : [];
    foreach ($items as &$itRapida) {
        $itRapida['total'] = round((float)($itRapida['cantidad'] ?? 0) * (float)($itRapida['precio'] ?? 0), 2);
        $itRapida['foto_producto'] = $itRapida['foto_producto'] ?? null;
        $itRapida['mostrar_foto_pdf'] = $itRapida['mostrar_foto_pdf'] ?? 0;
    }
    unset($itRapida);
}


/* Cargar plantilla de servicios en una cotización nueva. */
$plantilla_id = ($cotizacion_id === 0 && $_SERVER['REQUEST_METHOD'] !== 'POST') ? (int)($_GET['plantilla'] ?? 0) : 0;
if ($plantilla_id > 0) {
    try {
        $stp = srnu_db()->prepare('SELECT * FROM plantilla_items WHERE plantilla_id=? ORDER BY id');
        $stp->execute([$plantilla_id]);
        $plantilla_items = $stp->fetchAll();
        if ($plantilla_items) {
            $items = array_map(static function(array $it): array {
                return [
                    'concepto' => $it['concepto'],
                    'cantidad' => $it['cantidad'],
                    'precio' => $it['precio'],
                    'costo_interno' => $it['costo_interno'],
                    'total' => round((float)$it['cantidad'] * (float)$it['precio'], 2),
                    'responsable_sergio' => $it['responsable_sergio'],
                    'responsable_ricardo' => $it['responsable_ricardo'],
                    'responsable_tomas' => $it['responsable_tomas'],
                    'garantia_meses' => $it['garantia_meses'],
                    'catalogo_id' => $it['catalogo_id'],
                    'tipo_entrega' => $it['tipo_entrega'],
                    'dias_entrega_estimada' => $it['dias_entrega_estimada'],
                    'foto_producto' => srnu_foto_catalogo((int)($it['catalogo_id'] ?? 0)),
                    'mostrar_foto_pdf' => srnu_foto_catalogo((int)($it['catalogo_id'] ?? 0)) ? 1 : 0,
                ];
            }, $plantilla_items);
        }
    } catch (Throwable $e) { /* Plantillas son opcionales. */ }
}

/* Para generar el PDF desde Chrome se reutiliza exactamente el mismo documento
   guardado en la base de datos, simulando el envío del formulario. */
if ($modo_pdf && $cotizacion_id > 0 && $_SERVER['REQUEST_METHOD'] !== 'POST') {
    $guardada = srnu_obtener_cotizacion($cotizacion_id);
    if (!$guardada) {
        http_response_code(404);
        exit('Cotización no encontrada.');
    }
    $_POST = [
        'modo' => 'generar',
        'cotizacion_id' => $cotizacion_id,
        'cliente' => $guardada['cliente'],
        'telefono' => $guardada['telefono'],
        'cliente_id' => $guardada['cliente_id'] ?? 0,
        'vehiculo' => $guardada['vehiculo'],
        'fecha' => $guardada['fecha'],
        'requiere_factura' => $guardada['requiere_factura'],
        'concepto' => array_column($guardada['items'], 'concepto'),
        'cantidad' => array_column($guardada['items'], 'cantidad'),
        'precio' => array_column($guardada['items'], 'precio'),
        'costo_interno' => array_column($guardada['items'], 'costo_interno'),
        'garantia_meses' => array_column($guardada['items'], 'garantia_meses'),
        'catalogo_id' => array_column($guardada['items'], 'catalogo_id'),
        'tipo_entrega' => array_column($guardada['items'], 'tipo_entrega'),
        'dias_entrega_estimada' => array_column($guardada['items'], 'dias_entrega_estimada'),
        'foto_producto_actual' => array_column($guardada['items'], 'foto_producto'),
        'mostrar_foto_pdf' => array_map(static fn(array $x): int => !empty($x['mostrar_foto_pdf']) ? 1 : 0, $guardada['items']),
        'quitar_foto' => array_fill(0, count($guardada['items']), 0),
        'responsables' => array_map(static function (array $item): string {
            $r = [];
            if (!empty($item['responsable_sergio'])) $r[] = 'sergio';
            if (!empty($item['responsable_ricardo'])) $r[] = 'ricardo';
            if (!empty($item['responsable_tomas'])) $r[] = 'tomas';
            return implode(',', $r);
        }, $guardada['items']),
        'msi_plazos' => array_values(array_diff($guardada['msi_plazos'], ['bbva_pyme', 'tarjeta_1x'])),
        'bbva_pyme' => in_array('bbva_pyme', $guardada['msi_plazos'], true) ? '1' : '0',
        'tarjeta_una_exhibicion' => '1',
        'anticipo_tipo' => $guardada['anticipo_tipo'] ?? 'porcentaje',
        'anticipo_valor' => $guardada['anticipo_valor'] ?? 70.00,
        'conservar_anticipo_recibido' => !empty($guardada['conservar_anticipo_recibido']) ? '1' : '0',
        'anticipo_recibido_monto' => $guardada['anticipo_recibido_monto'] ?? 0.00,
        'dividir_anticipo' => !empty($guardada['dividir_anticipo']) ? '1' : '0',
        'repartir_igual' => !empty($guardada['repartir_igual']) ? '1' : '0',
        'anticipo_sergio' => $guardada['anticipo_sergio'] ?? 0.00,
        'anticipo_ricardo' => $guardada['anticipo_ricardo'] ?? 0.00,
        'anticipo_tomas' => $guardada['anticipo_tomas'] ?? 0.00,
        'participa_sergio' => !isset($guardada['participa_sergio']) || $guardada['participa_sergio'] ? '1' : '0',
        'participa_ricardo' => !isset($guardada['participa_ricardo']) || $guardada['participa_ricardo'] ? '1' : '0',
        'participa_tomas' => !empty($guardada['participa_tomas']) ? '1' : '0',
        'estado' => $guardada['estado'] ?? 'Cotización',
        'vigencia_dias' => $guardada['vigencia_dias'] ?? 15,
        'dias_trabajo_general_min' => $guardada['dias_trabajo_general_min'] ?? 0,
        'dias_trabajo_general_max' => $guardada['dias_trabajo_general_max'] ?? 0,
    ];
    $_SERVER['REQUEST_METHOD'] = 'POST';
}

/* Precargar cliente desde el registro al crear una nueva cotización. */
if ($cotizacion_id <= 0 && $_SERVER['REQUEST_METHOD'] !== 'POST' && isset($_GET['cliente_id'])) {
    $cliente_pre = srnu_obtener_cliente((int)$_GET['cliente_id']);
    if ($cliente_pre) {
        $cliente_id = (int)$cliente_pre['id'];
        $cliente = (string)$cliente_pre['nombre'];
        $telefono = (string)$cliente_pre['telefono'];
    }
}

/* ==========================================================
   PROCESAMIENTO DEL FORMULARIO
   ========================================================== */

if ($_SERVER["REQUEST_METHOD"] == "POST") {

    $modo = $_POST['modo'] ?? 'generar';
    $cotizacion_id = (int)($_POST['cotizacion_id'] ?? $cotizacion_id);

    $cliente = trim($_POST['cliente'] ?? '');
    $telefono = trim($_POST['telefono'] ?? '');
    $cliente_id = max(0, (int)($_POST['cliente_id'] ?? 0));
    $vehiculo = trim($_POST['vehiculo'] ?? '');

    $fecha_raw = $_POST['fecha'] ?? date('Y-m-d');

    $requiere_factura = $_POST['requiere_factura'] ?? 'si';
    $bbva_pyme = (($_POST['bbva_pyme'] ?? '0') === '1');
    $tarjeta_una_exhibicion = true;
    $anticipo_tipo = in_array(($_POST['anticipo_tipo'] ?? 'porcentaje'), ['porcentaje','monto'], true) ? $_POST['anticipo_tipo'] : 'porcentaje';
    $anticipo_valor = (float)($_POST['anticipo_valor'] ?? 70);
    if ($anticipo_valor < 0) $anticipo_valor = 0;
    $conservar_anticipo_recibido = (($_POST['conservar_anticipo_recibido'] ?? '0') === '1');
    $anticipo_recibido_monto = max(0, (float)($_POST['anticipo_recibido_monto'] ?? 0));
    $dividir_anticipo = (($_POST['dividir_anticipo'] ?? '0') === '1');
    $repartir_igual = (($_POST['repartir_igual'] ?? '0') === '1');
    $anticipo_sergio = max(0, (float)($_POST['anticipo_sergio'] ?? 0));
    $anticipo_ricardo = max(0, (float)($_POST['anticipo_ricardo'] ?? 0));
    $anticipo_tomas = max(0, (float)($_POST['anticipo_tomas'] ?? 0));
    $participa_sergio = (($_POST['participa_sergio'] ?? '0') === '1');
    $participa_ricardo = (($_POST['participa_ricardo'] ?? '0') === '1');
    $participa_tomas = (($_POST['participa_tomas'] ?? '0') === '1');
    $estados_validos = ['Cotización','Aprobada','Anticipo recibido','Vehículo recibido','En proceso','Terminado','Entregado','Cancelado'];
    $estado = in_array($_POST['estado'] ?? 'Cotización', $estados_validos, true) ? $_POST['estado'] : 'Cotización';
    $vigencia_dias = max(1, min(365, (int)($_POST['vigencia_dias'] ?? 15)));
    $dias_trabajo_general_min = max(0, min(365, (int)($_POST['dias_trabajo_general_min'] ?? 0)));
    $dias_trabajo_general_max = max(0, min(365, (int)($_POST['dias_trabajo_general_max'] ?? 0)));
    if ($dias_trabajo_general_max > 0 && $dias_trabajo_general_min > $dias_trabajo_general_max) { [$dias_trabajo_general_min, $dias_trabajo_general_max] = [$dias_trabajo_general_max, $dias_trabajo_general_min]; }
    $motivo_version = trim((string)($_POST['motivo_version'] ?? 'Edición de cotización'));
    $guardar_articulos_catalogo = ($_POST['guardar_articulos_catalogo'] ?? '0') === '1';


    /* ======================================================
       FECHA
       ====================================================== */

    $meses = [
        1 => 'Enero',
        2 => 'Febrero',
        3 => 'Marzo',
        4 => 'Abril',
        5 => 'Mayo',
        6 => 'Junio',
        7 => 'Julio',
        8 => 'Agosto',
        9 => 'Septiembre',
        10 => 'Octubre',
        11 => 'Noviembre',
        12 => 'Diciembre'
    ];

    $ts = strtotime($fecha_raw);

    if ($ts) {

        $fecha =
            date('d', $ts) .
            ' / ' .
            $meses[(int)date('n', $ts)] .
            ' / ' .
            date('Y', $ts);

    } else {

        $fecha = $fecha_raw;

    }


    /* ======================================================
       CONCEPTOS
       ====================================================== */

    $conceptos = $_POST['concepto'] ?? [];
    $cantidades = $_POST['cantidad'] ?? [];
    $precios = $_POST['precio'] ?? [];
    $costos_internos = $_POST['costo_interno'] ?? [];
    $garantias_meses = $_POST['garantia_meses'] ?? [];
    $catalogo_ids = $_POST['catalogo_id'] ?? [];
    $tipos_entrega = $_POST['tipo_entrega'] ?? [];
    $dias_entrega_estimadas = $_POST['dias_entrega_estimada'] ?? [];
    $fotos_producto_actual = $_POST['foto_producto_actual'] ?? [];
    $mostrar_fotos_pdf = $_POST['mostrar_foto_pdf'] ?? [];
    $quitar_fotos = $_POST['quitar_foto'] ?? [];
    $responsables_filas = $_POST['responsables'] ?? [];

    $items = [];
    $subtotal = 0;

    for ($i = 0; $i < count($conceptos); $i++) {

        $concepto = trim($conceptos[$i] ?? '');
        $cantidad = (float)($cantidades[$i] ?? 0);
        $precio = (float)($precios[$i] ?? 0);
        $costo_interno = max(0, (float)($costos_internos[$i] ?? 0));
        $catalogo_id = (int)($catalogo_ids[$i] ?? 0);
        $tipo_entrega = in_array(($tipos_entrega[$i] ?? 'inmediata'), ['inmediata','sobre_pedido'], true) ? $tipos_entrega[$i] : 'inmediata';
        $garantia_meses = max(0, (int)($garantias_meses[$i] ?? 0));
        if ($tipo_entrega === 'sobre_pedido' && $garantia_meses <= 0) $garantia_meses = 12;
        $dias_entrega_estimada = max(0, (int)($dias_entrega_estimadas[$i] ?? 0));
        $foto_producto = trim((string)($fotos_producto_actual[$i] ?? ''));
        if (!empty($quitar_fotos[$i])) $foto_producto = '';
        if (!$modo_pdf) {
            $foto_producto = (string)(srnu_guardar_foto_producto_upload(srnu_archivo_upload_indice('foto_producto', $i), $foto_producto ?: null) ?? '');
        }
        if ($foto_producto === '' && $catalogo_id > 0) $foto_producto = (string)(srnu_foto_catalogo($catalogo_id) ?? '');
        $mostrar_foto_pdf = !empty($mostrar_fotos_pdf[$i]) ? 1 : 0;
        $responsables_raw = array_filter(array_map('trim', explode(',', (string)($responsables_filas[$i] ?? ''))));
        $responsable_sergio = in_array('sergio', $responsables_raw, true);
        $responsable_ricardo = in_array('ricardo', $responsables_raw, true);
        $responsable_tomas = in_array('tomas', $responsables_raw, true);

        if ($concepto !== '' && $cantidad > 0) {

            $total_item =
                round($cantidad * $precio, 2);

            $subtotal += $total_item;

            $items[] = [
                'concepto' => $concepto,
                'cantidad' => $cantidad,
                'precio' => $precio,
                'costo_interno' => $costo_interno,
                'garantia_meses' => $garantia_meses,
                'catalogo_id' => $catalogo_id > 0 ? $catalogo_id : null,
                'tipo_entrega' => $tipo_entrega,
                'dias_entrega_estimada' => $dias_entrega_estimada,
                'foto_producto' => $foto_producto ?: null,
                'mostrar_foto_pdf' => $mostrar_foto_pdf,
                'total' => $total_item,
                'responsable_sergio' => $responsable_sergio ? 1 : 0,
                'responsable_ricardo' => $responsable_ricardo ? 1 : 0,
                'responsable_tomas' => $responsable_tomas ? 1 : 0,
            ];
        }
    }


    /* ======================================================
       TOTALES
       ====================================================== */

    $subtotal = round($subtotal, 2);

    // Disponibilidad operativa de los conceptos. Solo se usa para condiciones del documento.
    $hay_sobre_pedido = false;
    $dias_sobre_pedido = 0;
    foreach ($items as $it) {
        if (($it['tipo_entrega'] ?? 'inmediata') === 'sobre_pedido') {
            $hay_sobre_pedido = true;
            $dias_sobre_pedido = max($dias_sobre_pedido, (int)($it['dias_entrega_estimada'] ?? 0));
        }
    }

    // BBVA PyME es una casilla manual (POST, cotización guardada o cotizador rápido).
    // Si está marcada, el servidor activa la factura sin depender del navegador.
    $bbva_pyme = (bool)$bbva_pyme;
    if ($bbva_pyme) {
        $requiere_factura = 'si';
        $tipo_pdf = 'factura';
    }

    $iva =
        ($requiere_factura === 'si')
        ? round($subtotal * 0.16, 2)
        : 0;

    $total_final =
        round($subtotal + $iva, 2);

    /*
     * Ambas modalidades siempre disponibles
     */

    $total_con_factura = srnu_tarjeta_total($subtotal, 'si');

    $total_sin_factura =
        round($subtotal, 2);

    $msi_factura_habilitado =
        ($total_con_factura <= $msi_limite_maximo);

    $msi_sin_factura_habilitado =
        ($total_sin_factura <= $msi_limite_maximo);

    /* ======================================================
       ANTICIPO PERSONALIZABLE
       - Porcentaje: 0 a 100%
       - Monto: de $0 al total de la modalidad
       ====================================================== */
    function srnu_calcular_anticipo(float $total, string $tipo, float $valor): array {
        if ($tipo === 'monto') {
            $monto = max(0, min($total, $valor));
            $porcentaje = $total > 0 ? ($monto / $total) * 100 : 0;
        } else {
            $porcentaje = max(0, min(100, $valor));
            $monto = round($total * ($porcentaje / 100), 2);
        }
        $saldo = round(max(0, $total - $monto), 2);
        $saldo_porcentaje = $total > 0 ? ($saldo / $total) * 100 : 0;
        return [
            'monto' => round($monto, 2),
            'porcentaje' => $porcentaje,
            'saldo' => $saldo,
            'saldo_porcentaje' => $saldo_porcentaje
        ];
    }

    /*
     * El anticipo SIEMPRE se calcula sobre el subtotal antes de IVA.
     * Si hay factura, el IVA queda completamente fuera del adelanto.
     *
     * Si el anticipo ya fue recibido, el monto histórico pagado manda:
     * agregar o quitar conceptos NO modifica automáticamente ese importe.
     * El cálculo normal se conserva como referencia administrativa.
     */
    $anticipo_teorico = srnu_calcular_anticipo($subtotal, $anticipo_tipo, $anticipo_valor);
    $anticipo_efectivo_monto = $conservar_anticipo_recibido
        ? round(max(0, $anticipo_recibido_monto), 2)
        : round($anticipo_teorico['monto'], 2);
    $anticipo_efectivo_porcentaje = $subtotal > 0
        ? ($anticipo_efectivo_monto / $subtotal) * 100
        : 0;

    $anticipo_base = [
        'monto' => $anticipo_efectivo_monto,
        'porcentaje' => $anticipo_efectivo_porcentaje,
        'saldo' => round(max(0, $subtotal - $anticipo_efectivo_monto), 2),
        'saldo_porcentaje' => $subtotal > 0
            ? (max(0, $subtotal - $anticipo_efectivo_monto) / $subtotal) * 100
            : 0,
    ];

    $anticipo_sin_factura = $anticipo_base;
    $anticipo_sin_factura['saldo'] = round(max(0, $total_sin_factura - $anticipo_efectivo_monto), 2);
    $anticipo_sin_factura['saldo_porcentaje'] = $total_sin_factura > 0
        ? ($anticipo_sin_factura['saldo'] / $total_sin_factura) * 100
        : 0;

    $anticipo_factura = $anticipo_base;
    $anticipo_factura['saldo'] = round(max(0, $total_con_factura - $anticipo_efectivo_monto), 2);
    $anticipo_factura['saldo_porcentaje'] = $total_con_factura > 0
        ? ($anticipo_factura['saldo'] / $total_con_factura) * 100
        : 0;

    $documento_con_factura = $modo_pdf
        ? ($tipo_pdf === 'factura')
        : ($requiere_factura === 'si');

    $pago_total_documento = $documento_con_factura ? $total_con_factura : $total_sin_factura;
    $anticipo_actual = $documento_con_factura ? $anticipo_factura : $anticipo_sin_factura;
    $anticipo_documento = $anticipo_actual['monto'];
    $anticipo_porcentaje_documento = $anticipo_actual['porcentaje'];
    $saldo_documento = $anticipo_actual['saldo'];
    $saldo_porcentaje_documento = $anticipo_actual['saldo_porcentaje'];
    $anticipo_teorico_documento = round((float)$anticipo_teorico['monto'], 2);
    $diferencia_anticipo_documento = round($anticipo_teorico_documento - $anticipo_documento, 2);
    $excedente_anticipo_documento = round(max(0, $anticipo_documento - $anticipo_teorico_documento), 2);

    /* División opcional del anticipo entre participantes activos. */
    if ($dividir_anticipo) {
        if (!$participa_sergio && !$participa_ricardo && !$participa_tomas) $participa_sergio = true;
        if (!$participa_sergio) $anticipo_sergio = 0.00;
        if (!$participa_ricardo) $anticipo_ricardo = 0.00;
        if (!$participa_tomas) $anticipo_tomas = 0.00;
        $activos = [];
        if ($participa_sergio) $activos[] = 'sergio';
        if ($participa_ricardo) $activos[] = 'ricardo';
        if ($participa_tomas) $activos[] = 'tomas';

        /* Modo opcional: repartir el 100% por igual únicamente entre
           los participantes seleccionados. El último absorbe los centavos
           restantes para que la suma siempre sea exacta. */
        if ($repartir_igual && count($activos) > 0) {
            $total_centavos = (int) round($anticipo_documento * 100);
            $base_centavos = intdiv($total_centavos, count($activos));
            $resto_centavos = $total_centavos - ($base_centavos * count($activos));
            foreach (['sergio','ricardo','tomas'] as $persona) {
                if (!in_array($persona, $activos, true)) ${'anticipo_' . $persona} = 0.00;
            }
            foreach ($activos as $i => $persona) {
                $centavos = $base_centavos + (($i === count($activos) - 1) ? $resto_centavos : 0);
                ${'anticipo_' . $persona} = $centavos / 100;
            }
        }

        $suma_division = round($anticipo_sergio + $anticipo_ricardo + $anticipo_tomas, 2);
        if (!$repartir_igual && abs($suma_division - round($anticipo_documento, 2)) > 0.01) {
            /* En modo manual nunca se iguala automáticamente. Se conserva la proporción capturada.
               Si todos los montos están en cero, el primer participante activo
               absorbe el anticipo completo hasta que el usuario haga su reparto. */
            $pesos = [];
            $suma_pesos = 0.00;
            foreach ($activos as $persona) {
                $v = max(0.00, (float) ${'anticipo_' . $persona});
                $pesos[$persona] = $v;
                $suma_pesos += $v;
            }

            $restante = round($anticipo_documento, 2);
            foreach (['sergio','ricardo','tomas'] as $persona) {
                if (!in_array($persona, $activos, true)) ${'anticipo_' . $persona} = 0.00;
            }

            foreach ($activos as $i => $persona) {
                if ($i === count($activos) - 1) {
                    $m = $restante;
                } elseif ($suma_pesos > 0) {
                    $m = floor(($anticipo_documento * ($pesos[$persona] / $suma_pesos)) * 100) / 100;
                } else {
                    $m = ($i === 0) ? round($anticipo_documento, 2) : 0.00;
                }
                ${'anticipo_' . $persona} = round(max(0.00, $m), 2);
                $restante = round($restante - ${'anticipo_' . $persona}, 2);
            }
        }
    }
    $porcentaje_sergio_anticipo = ($dividir_anticipo && $participa_sergio && $anticipo_documento > 0) ? ($anticipo_sergio / $anticipo_documento) * 100 : 0;
    $porcentaje_ricardo_anticipo = ($dividir_anticipo && $participa_ricardo && $anticipo_documento > 0) ? ($anticipo_ricardo / $anticipo_documento) * 100 : 0;
    $porcentaje_tomas_anticipo = ($dividir_anticipo && $participa_tomas && $anticipo_documento > 0) ? ($anticipo_tomas / $anticipo_documento) * 100 : 0;

    /* Resumen administrativo interno. Nunca se imprime en el PDF final. */
    $iva_resumen_interno = $documento_con_factura ? round($subtotal * 0.16, 2) : 0.00;
    $resumen_interno = srnu_resumen_interno(
        $items,
        $subtotal,
        $iva_resumen_interno,
        $dividir_anticipo,
        $anticipo_sergio,
        $anticipo_ricardo,
        $anticipo_tomas
    );


    /* ======================================================
       TASAS CLIP — MESES SIN INTERESES
       ====================================================== */

    $reglas_tarjeta = srnu_tarjeta_reglas();
    $clip_comision_base = $reglas_tarjeta['clip']['base'];
    $clip_cargo_fijo = $reglas_tarjeta['clip']['cargo'];
    $clip_iva = $reglas_tarjeta['clip']['iva_comision'];
    $clip_sobretasas = $reglas_tarjeta['clip']['sobretasas'];
    $bbva_comision_base = $reglas_tarjeta['bbva']['base'];
    $bbva_sobretasas = $reglas_tarjeta['bbva']['sobretasas'];


    // Todos los MSI se incluyen automáticamente, también en cotizaciones antiguas.
    $msi_plazos_sel = srnu_tarjeta_plazos_disponibles($subtotal, (string)$requiere_factura, (bool)$bbva_pyme);
    $msi_opciones_factura = [];
    $msi_opciones_sin_factura = [];
    $msi_no_disponible_factura = [];
    $msi_no_disponible_sin_factura = [];
    $tarjeta_una_exhibicion_factura = null;
    $tarjeta_una_exhibicion_sin_factura = null;
    $bbva_una_exhibicion = null;

    if ($modo === 'generar') {
        if (!empty($items)) {
            $tarjeta_una_exhibicion_factura = srnu_clip_cobro($total_con_factura, 0);
            $tarjeta_una_exhibicion_sin_factura = srnu_clip_cobro($total_sin_factura, 0);
            if ($bbva_pyme && srnu_bbva_una_exhibicion_disponible($subtotal)) $bbva_una_exhibicion = srnu_bbva_cobro($subtotal, 0);
        }

        if (!empty($items)) {
            // No ofrecer ni imprimir MSI Clip que superen su límite final.
            foreach ($clip_sobretasas as $plazo => $sobretasa) {
                foreach (['factura'=>$total_con_factura, 'sin_factura'=>$total_sin_factura] as $tipo => $base_total) {
                    $precio_msi = srnu_clip_cobro($base_total, (int)$plazo);
                    if ($precio_msi > $msi_limite_maximo) continue;
                    $opcion = [
                        'plazo'=>$plazo, 'precio_msi'=>$precio_msi,
                        'pago_mensual'=>$precio_msi / $plazo,
                    ];
                    if ($tipo === 'factura') $msi_opciones_factura[] = $opcion;
                    else $msi_opciones_sin_factura[] = $opcion;
                }
            }
            if ($bbva_pyme) {
                foreach (srnu_bbva_plazos_disponibles($subtotal) as $plazo) {
                    $plazo = (int)$plazo;
                    $sobretasa = $bbva_sobretasas[$plazo];
                    $precio_msi = srnu_bbva_cobro($subtotal, (int)$plazo);
                    $bbva_opciones[] = [
                        'plazo'=>$plazo, 'sobretasa'=>$sobretasa,
                        'tasa_total'=>$bbva_comision_base + $sobretasa,
                        'precio_msi'=>$precio_msi, 'pago_mensual'=>$precio_msi / $plazo,
                    ];
                }
            }
        }

        /* Guardar / actualizar en MySQL después de recalcular todos los importes.
           Ver/Imprimir PDF nunca debe modificar ni versionar la cotización. */
        try {
            if (!$modo_pdf) {
            $cotizacion_id = srnu_guardar_cotizacion([
                'cliente' => $cliente,
                'telefono' => $telefono,
                'cliente_id' => $cliente_id,
                'vehiculo' => $vehiculo,
                'fecha_raw' => $fecha_raw,
                'requiere_factura' => $requiere_factura,
                'subtotal' => $subtotal,
                'iva' => $iva,
                'total' => $total_final,
                'msi_plazos' => array_values(array_merge(
                    $msi_plazos_sel,
                    $bbva_pyme ? ['bbva_pyme'] : [],
                    $tarjeta_una_exhibicion ? ['tarjeta_1x'] : []
                )),
                'anticipo_tipo' => $anticipo_tipo,
                'anticipo_valor' => $anticipo_valor,
                'conservar_anticipo_recibido' => $conservar_anticipo_recibido ? 1 : 0,
                'anticipo_recibido_monto' => $conservar_anticipo_recibido ? $anticipo_documento : $anticipo_recibido_monto,
                'dividir_anticipo' => $dividir_anticipo ? 1 : 0,
                'repartir_igual' => $repartir_igual ? 1 : 0,
                'anticipo_sergio' => $anticipo_sergio,
                'anticipo_ricardo' => $anticipo_ricardo,
                'anticipo_tomas' => $anticipo_tomas,
                'participa_sergio' => $participa_sergio ? 1 : 0,
                'participa_ricardo' => $participa_ricardo ? 1 : 0,
                'participa_tomas' => $participa_tomas ? 1 : 0,
                'estado' => $estado,
                'vigencia_dias' => $vigencia_dias,
                'dias_trabajo_general_min' => $dias_trabajo_general_min,
                'dias_trabajo_general_max' => $dias_trabajo_general_max,
                'motivo_version' => $motivo_version,
                'guardar_articulos_catalogo' => $guardar_articulos_catalogo ? 1 : 0,
            ], $items, $cotizacion_id);
            $guardada = srnu_obtener_cotizacion($cotizacion_id);
            $folio = $guardada['folio'] ?? '';
            if ($guardar_articulos_catalogo && $guardada) {
                $items = $guardada['items'];
                $catalogo_servicios = srnu_catalogo_activo();
            }
            } else {
                $guardada = srnu_obtener_cotizacion($cotizacion_id);
                $folio = $guardada['folio'] ?? $folio;
            }
        } catch (Throwable $e) {
            $error_bd = 'No se pudo guardar la cotización en MySQL: ' . $e->getMessage();
        }

        $cotizacion_generada = true;
    }
}


/* Firma digital vigente de esta cotización. Solo se imprime si corresponde
   exactamente a la versión actual del documento. */
$firma_digital_actual = null;
$firma_digital_valida = false;
if ($cotizacion_id > 0) {
    try {
        $cot_firma = srnu_obtener_cotizacion($cotizacion_id);
        $firma_digital_actual = srnu_obtener_firma_digital($cotizacion_id);
        if ($cot_firma && $firma_digital_actual) {
            $firma_digital_valida = srnu_firma_digital_es_valida($cot_firma, $firma_digital_actual);
        }
    } catch (Throwable $e) {
        $firma_digital_actual = null;
        $firma_digital_valida = false;
    }
}


/* Firma interna vigente del taller. */
$firma_taller_actual = null;
$firma_taller_valida = false;
if ($cotizacion_id > 0) {
    try {
        if (!isset($cot_firma) || !$cot_firma) $cot_firma = srnu_obtener_cotizacion($cotizacion_id);
        $firma_taller_actual = srnu_obtener_firma_taller($cotizacion_id);
        if ($cot_firma && $firma_taller_actual) {
            $firma_taller_valida = srnu_firma_taller_es_valida($cot_firma, $firma_taller_actual);
        }
    } catch (Throwable $e) {
        $firma_taller_actual = null;
        $firma_taller_valida = false;
    }
}


/* Confirmación local vigente como alternativa a la firma dibujada. */
$confirmacion_local_actual = null;
$confirmacion_local_valida = false;
if ($cotizacion_id > 0) {
    try {
        if (!isset($cot_firma) || !$cot_firma) $cot_firma = srnu_obtener_cotizacion($cotizacion_id);
        $confirmacion_local_actual = srnu_obtener_confirmacion_local($cotizacion_id);
        if ($cot_firma && $confirmacion_local_actual) {
            $confirmacion_local_valida = srnu_confirmacion_local_es_valida($cot_firma, $confirmacion_local_actual);
        }
    } catch (Throwable $e) {
        $confirmacion_local_actual = null;
        $confirmacion_local_valida = false;
    }
}

