    width: 1px;
    height: 48px;
    background: #555;
}

.segunda-logos {
    display: flex;
    align-items: center;
    gap: 8px;
}

.segunda-logos img {
    width: 82px;
    height: 48px;
    object-fit: contain;
    background: #000;
    border-radius: 5px;
}



/* ==========================================================
   TITULO
   ========================================================== */

.titulo-orden {

    text-align: center;

    margin: 25px 0 10px;

}


.titulo-orden h1 {

    font-size: 22px;

    letter-spacing: 1px;

    margin: 0;

}


.meta-row {

    display: flex;

    justify-content: space-between;

    padding: 0 50px;

    margin-bottom: 20px;

    font-weight: bold;

    font-size: 14px;

}


.contenido {

    padding: 0 50px;

}


/* ==========================================================
   TITULOS DE SECCION
   ========================================================== */

.seccion-titulo {

    display: flex;

    align-items: center;

    gap: 12px;

    margin: 25px 0 14px;

    padding-bottom: 10px;

    border-bottom: 2px solid #111;

}


.seccion-titulo > span {

    width: 32px;

    height: 32px;

    min-width: 32px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #111;

    color: #fff;

    border-radius: 50%;

    font-weight: bold;

    font-size: 12px;

}


.seccion-titulo strong {

    display: block;

    font-size: 14px;

    letter-spacing: .7px;

}


.seccion-titulo small {

    display: block;

    margin-top: 3px;

    color: #777;

    font-size: 10px;

}


/* ==========================================================
   TABLA COTIZACION
   ========================================================== */

table.cotizacion {

    width: 100%;

    border-collapse: collapse;

    font-size: 14px;

}


table.cotizacion thead th {

    background: var(--negro);

    color: #fff;

    padding: 10px 12px;

    text-align: left;

    font-weight: 500;

}


table.cotizacion thead th:not(:first-child) {

    text-align: center;

}


table.cotizacion tbody td {

    padding: 11px 12px;

    border-bottom: 1px solid #ddd;

}


table.cotizacion tbody td:not(:first-child) {

    text-align: center;

}


/* ==========================================================
   TOTALES
   ========================================================== */

.totales {

    margin-top: 25px;

    width: 280px;

    margin-left: auto;

    font-size: 14px;

}


.totales .fila {

    display: flex;

    justify-content: space-between;

    padding: 6px 0;

    border-bottom: 1px solid #999;

}


.totales .fila.total-final {

    border-top: 2px solid #111;

    border-bottom: none;

    margin-top: 5px;

    padding-top: 9px;

    font-weight: bold;

    font-size: 17px;

}


/* ==========================================================
   RESUMEN
   ========================================================== */

.resumen-importante {

    margin-top: 40px;

    padding: 16px;

    border: 1px solid var(--borde);

    background: #f8f9fb;

    display: flex;

    gap: 12px;

    align-items: center;

}


.resumen-icono {

    width: 34px;

    height: 34px;

    min-width: 34px;

    border-radius: 50%;

    background: var(--azul);

    color: #fff;

    display: flex;

    align-items: center;

    justify-content: center;

    font-weight: bold;

}


.resumen-importante strong {

    font-size: 12px;

}


.resumen-importante p {

    margin: 4px 0 0;

    font-size: 11px;

    color: #666;

}


/* ==========================================================
   SEGUNDA HOJA
   ========================================================== */

.page-break {

    display: block;

    height: 0;

}


.segunda-hoja {

    min-height: 1050px;

    padding: 40px 50px 20px;

}


.segunda-header {

    display: flex;

    justify-content: space-between;

    align-items: center;

    border-bottom: 3px solid #111;

    padding-bottom: 15px;

}


.segunda-header strong {

    display: block;

    font-size: 21px;

    letter-spacing: 1px;

}


.segunda-header span {

    display: block;

    color: #777;

    font-size: 10px;

    margin-top: 3px;

}


.segunda-header img {

    width: 110px;

}


.segunda-titulo {

    margin: 35px 0 25px;

}


.segunda-titulo h1 {

    margin: 0;

    font-size: 25px;

}


.segunda-titulo p {

    margin: 5px 0 0;

    color: #777;

    font-size: 12px;

}


/* ==========================================================
   PAGOS
   ========================================================== */

.pago-principal {

    border: 1px solid var(--borde);

    border-radius: 8px;

    overflow: hidden;

}


.pago-total {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 16px 20px;

    background: #f5f6f8;

}


.pago-total span {

    font-size: 12px;

    color: #666;

}


.pago-total strong {

    font-size: 23px;

}


.anticipo-box {

    text-align: center;

    padding: 25px;

    background: #111;

    color: #fff;

}


.anticipo-label {

    font-size: 11px;

    letter-spacing: 1px;

    font-weight: bold;

}


.anticipo-porcentaje {

    font-size: 34px;

    font-weight: 800;

    margin-top: 5px;

}


.anticipo-monto {

    font-size: 30px;

    font-weight: 800;

    margin-top: 2px;

}


.anticipo-texto {

    font-size: 10px;

    color: #bbb;

    margin-top: 5px;

}


.saldo-box {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 15px 20px;

}


.saldo-box span {

    display: block;

    font-size: 11px;

    color: #777;

}


.saldo-box strong {

    display: block;

    font-size: 18px;

    margin-top: 2px;

}


.saldo-porcentaje {

    font-weight: bold;

    font-size: 16px;

    color: #555;

}


/* ==========================================================
   MSI
   ========================================================== */

.msi-seccion {

    margin-top: 35px;

}


.msi-box {

    margin-top: 12px;

    border: 2px solid var(--azul);

    border-radius: 7px;

    overflow: hidden;

}


.msi-title {

    background: var(--azul);

    color: #fff;

    font-weight: bold;

    text-align: center;

    padding: 9px;

    font-size: 12px;

    letter-spacing: .5px;

}


.msi-row {

    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 10px 16px;

    border-bottom: 1px solid #e2e2e2;

    font-size: 13px;

}


.msi-row:last-child {

    border-bottom: none;

}


.msi-monto {

    text-align: right;

}


.msi-row strong {

    font-size: 14px;

}


.msi-mensual {

    display: block;

    font-size: 11px;

    color: #666;

    margin-top: 2px;

}


/* ==========================================================
   AVISO
   ========================================================== */

.anuncio-pedido {

    margin-top: 28px;

    border: 1px solid #cfd5df;

    border-left: 5px solid var(--azul);

    background: #f8fafc;

    border-radius: 6px;

    padding: 16px 18px;

    font-size: 12.2px;

    line-height: 1.62;

    color: #2c3440;

}


.anuncio-pedido > div {

    margin-top: 7px;

}


.anuncio-pedido .anuncio-titulo {

    margin-top: 0;

    font-size: 13.4px;

    font-weight: 900;

    letter-spacing: .8px;

    color: #111;

    text-transform: uppercase;

}


.anuncio-sub {

    font-size: 10px;

    color: #687386;

}


/* ==========================================================
   FIRMAS
   ========================================================== */

.firmas {

    display: flex;

    justify-content: space-around;

    margin: 55px 20px 15px;

}


.firmas div {

    text-align: center;

}


.firmas hr {

    width: 220px;

    border: none;

    border-top: 1px solid #333;

    margin-bottom: 6px;

}


.firmas p {

    margin: 0;

    font-size: 12px;

}


.firma-digital-img {
    display: block;
    width: 190px;
    height: 72px;
    object-fit: contain;
    margin: -40px auto 2px;
}
.firma-digital-meta {
    display: block;
    max-width: 240px;
    margin: 3px auto 0;
    font-size: 8px;
    line-height: 1.25;
    color: #687386;
}
.firma-digital-badge {
    display: inline-block;
    margin-top: 3px;
    padding: 2px 5px;
    border-radius: 8px;
    border: 1px solid #9ccbb0;
    color: #176b3a;
    font-size: 7px;
    font-weight: 800;
    letter-spacing: .25px;
    text-transform: uppercase;
}


/* ==========================================================
   FOOTER
   ========================================================== */

.footer-info {

    text-align: left;

    padding: 0 0 25px;

    font-size: 11px;

    line-height: 1.5;

    color: #333;

}


.footer-info strong {

    font-size: 12px;

}


.footer-banner {

    position: relative;

    background: var(--negro);

    min-height: 60px;

    clip-path:
        polygon(
            0 45%,
            100% 0,
            100% 100%,
            0 100%
        );

}


.footer-banner::after {

    content: "";

    position: absolute;

    inset: 0;

    background:
        linear-gradient(
            115deg,
            transparent 62%,
            var(--azul) 63%,
            var(--azul) 72%,
            transparent 73%
        );

}




/* ==========================================================
   HOJA 3 · CUENTAS Y RESPONSABLES
   ========================================================== */

.tercera-hoja {
    min-height: 1050px;
    padding: 40px 50px 20px;
    position: relative;
}

.tercera-titulo {
    margin: 35px 0 25px;
}

.tercera-titulo h1 {
    margin: 0;
    font-size: 25px;
}

.tercera-titulo p {
    margin: 6px 0 0;
    color: #777;
    font-size: 12px;
}

.bank-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 12px;
}

.bank-card {
    border: 1px solid var(--borde);
    border-radius: 9px;
    overflow: hidden;
    background: #fafafa;
    break-inside: avoid;
}

.bank-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    padding: 10px 14px;
    background: #111;
    color: #fff;
}

.bank-header strong {
    font-size: 13px;
}

.bank-header span {
    font-size: 9px;
    opacity: .75;
    text-align: right;
}

.bank-info {
    padding: 12px 14px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px 20px;
}

.bank-info div {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.bank-info label {
    font-size: 9px;
    color: #777;
    text-transform: uppercase;
    font-weight: 700;
}

.bank-info strong {
    font-size: 12px;
    color: #222;
}

.account-number {
    font-size: 16px !important;
    letter-spacing: .7px;
}

.bank-responsible {
    grid-column: 1 / -1;
    border-top: 1px solid #e1e1e1;
    padding-top: 8px;
}

.bank-responsible span {
    font-size: 9px;
    color: #777;
}

.bank-responsible strong {
    font-size: 11px;
}

.payment-warning {
    margin-top: 14px;
    padding: 12px 14px;
    border: 1px solid #d5d9e0;
    border-left: 4px solid var(--azul);
    border-radius: 7px;
    background: #f7f8fa;
    color: #444;
    font-size: 10.5px;
    line-height: 1.5;
}

.team-title {
    margin-top: 28px;
}

.team-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
}

.team-card {
    border: 1px solid var(--borde);
    border-radius: 8px;
    padding: 13px 10px;
    text-align: center;
    background: #fafafa;
    break-inside: avoid;
}

.team-card strong {
    display: block;
    font-size: 12px;
}

.team-card span {
    display: block;
    margin-top: 4px;
    color: #666;
    font-size: 9.5px;
}

.firma-title {
    margin-top: 28px;
}

/* ==========================================================
   BOTONES
   ========================================================== */

.acciones {
    width: min(980px, calc(100% - 32px));
    margin: 24px auto 36px;
    padding: 16px;
    display: flex;
    justify-content: center;
    align-items: stretch;
    flex-wrap: wrap;
    gap: 12px;
    background: #ffffff;
    border: 1px solid #e2e2e2;
    border-radius: 14px;
    box-shadow: 0 8px 24px rgba(0,0,0,.08);
}

.print-actions {
    display: contents;
}

.acciones .btn,
.acciones a.btn,
.acciones > a {
    min-width: 180px;
    min-height: 46px;
    margin: 0 !important;
    padding: 12px 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 9px;
    text-decoration: none;
    font-weight: 800;
    font-size: 13px;
    line-height: 1.2;
    text-align: center;
    border: 0;
    cursor: pointer;
}

.btn-factura { background: #111; color: #fff; }
.btn-sin-factura { background: #4a4a4a; color: #fff; }
.acciones .btn-descargar { background: #174da8; color: #fff; }
.acciones .btn-descargar-sin-factura { background: #eef3ff; color: #174da8; border: 1px solid #cddcff; }
.acciones .btn-editar { background: var(--azul); color: #fff; }
.acciones .btn-historial { background: #eef3ff; color: #174da8; border: 1px solid #cddcff; }
.acciones .btn-nueva { background: #fff; color: #222; border: 1px solid #cfcfcf; }

@media (max-width: 720px) {
    .acciones { width: calc(100% - 20px); padding: 12px; gap: 9px; }
    .acciones .btn, .acciones a.btn, .acciones > a { width: 100%; min-width: 0; }
}

/* ==========================================================
   ETIQUETA IMPRESION
   ========================================================== */

.print-only-label {

    display: none;

}


/* ==========================================================
   IMPRESION
   ========================================================== */

@page {

    size: letter;

    margin: 10mm;

}


@media print {

    html,
    body {

        background: #fff !important;

        margin: 0 !important;

        padding: 0 !important;

    }


    .form-wrap {

        display: none !important;

    }


    .acciones {

        display: none !important;

    }


    .page {

        width: 100%;

        max-width: none;

        margin: 0;

        box-shadow: none;

        overflow: visible;

    }


    .print-only-label {

        display: block;

        position: absolute;

        top: 8px;

        right: 10px;

        font-size: 8px;

        color: #777;

        text-transform: uppercase;

    }


    .banner,
    .footer-banner,
    table.cotizacion thead th,
    .msi-title,
    .anticipo-box {

        -webkit-print-color-adjust: exact !important;

        print-color-adjust: exact !important;

    }


    .page-break {

        display: block;

        page-break-after: always;

        break-after: page;

        height: 0;

    }


    .segunda-hoja {

        page-break-before: always;

        break-before: page;

        min-height: auto;

    }

    .tercera-hoja {
        page-break-before: always;
        break-before: page;
        min-height: auto;
    }

    .logos-header {
        position: relative;
        top: auto;
        right: auto;
        width: fit-content;
        margin: -155px 25px 18px auto;
    }

    .logo-item {
        width: 125px;
        height: 60px;
    }

    .bank-card,
    .team-card,
    .payment-warning {
        page-break-inside: avoid;
        break-inside: avoid;
    }


    .seccion-titulo,
    .pago-principal,
    .msi-box,
    .anuncio-pedido,
    .firmas {

        page-break-inside: avoid;

        break-inside: avoid;

    }

}


/* ==========================================================
   CORRECCIÓN FINAL DE IMPRESIÓN Y PAGINACIÓN SRNU CUSTOM
   ========================================================== */

.srnu-only-logo {
    position: absolute !important;
    top: 18px !important;
    right: 28px !important;
    margin: 0 !important;
    width: 150px !important;
    height: 82px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: #fff !important;
    z-index: 20 !important;
}

.srnu-logo-box {
    width: 150px;
    height: 82px;
    background: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    border-radius: 8px;
}

.srnu-logo-box img {
    display: block !important;
    width: 125px !important;
    height: auto !important;
    max-height: 72px !important;
    object-fit: contain !important;
}

.segunda-header > img {
    width: 125px !important;
    max-height: 62px !important;
    object-fit: contain !important;
    display: block !important;
}

.segunda-hoja, .tercera-hoja {
    box-sizing: border-box !important;
    min-height: 1050px;
    overflow: hidden;
}

.cuentas-transferencia {
    margin-top: 18px;
    padding: 14px;
    border: 1px solid #d9dce2;
    border-radius: 12px;
    background: #fff;
    page-break-inside: avoid;
    break-inside: avoid;
}

.cuentas-transferencia-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 12px;
}

.cuentas-transferencia-header strong {
    font-size: 13px;
    letter-spacing: .5px;
}

.cuentas-transferencia-header span {
    font-size: 10px;
    color: #666;
    text-align: right;
}

.cuentas-transferencia .bank-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin: 0;
}

.cuentas-transferencia .bank-card {
    min-width: 0;
    margin: 0 !important;
    padding: 12px !important;
    page-break-inside: avoid;
    break-inside: avoid;
}

.cuentas-transferencia .bank-card:last-child {
    grid-column: 1 / -1;
}

.cuentas-transferencia .bank-info {
    gap: 7px !important;
}

.cuentas-transferencia .account-number {
    font-size: 12px !important;
    white-space: nowrap !important;
    letter-spacing: .2px;
}

.cuentas-transferencia .payment-warning {
    margin-top: 10px !important;
    font-size: 10px !important;
    line-height: 1.35 !important;
}

@media screen {
    .page {
        max-width: 850px;
        margin: 30px auto;
    }
    .page-break {
        height: 28px !important;
        display: block !important;
        border: 0 !important;
    }
}

@media print {
    @page {
        size: Letter portrait;
        margin: 8mm;
    }

    html, body {
        margin: 0 !important;
        padding: 0 !important;
        background: #fff !important;
    }

    .page {
        width: 100% !important;
        max-width: none !important;
        margin: 0 !important;
        padding: 0 !important;
        box-shadow: none !important;
        background: #fff !important;
    }

    .page-break {
        height: 0 !important;
        display: block !important;
        page-break-after: always !important;
        break-after: page !important;
    }

    .segunda-hoja {
        page-break-before: auto !important;
        break-before: auto !important;
        page-break-after: always !important;
        break-after: page !important;
        min-height: auto !important;
    }

    .tercera-hoja {
        page-break-before: auto !important;
        break-before: auto !important;
        min-height: auto !important;
    }

    .srnu-only-logo {
        position: absolute !important;
        top: 10px !important;
        right: 18px !important;
        margin: 0 !important;
    }

    .acciones, #form-editar {
        display: none !important;
    }

    .cuentas-transferencia {
        page-break-inside: avoid !important;
        break-inside: avoid !important;
    }
}


/* ==========================================================
   CORRECCIÓN DEFINITIVA DE PAGINACIÓN Y LOGOS
   ========================================================== */

/* El logo SRNU ya viene recortado al contenido real */
.srnu-only-logo {
    background: #fff !important;
    border-radius: 8px !important;
    padding: 8px !important;
    box-sizing: border-box !important;
}
.srnu-logo-box {
    background: #fff !important;
    width: 150px !important;
    height: 72px !important;
    border-radius: 6px !important;
}
.srnu-logo-box img {
    width: 138px !important;
    max-height: 60px !important;
    height: auto !important;
    object-fit: contain !important;
}

/* Evitar que SRNU desaparezca sobre fondos negros en las hojas 2 y 3 */
.segunda-header > img {
    background: #fff !important;
    border-radius: 6px !important;
    padding: 6px !important;
    box-sizing: border-box !important;
    width: 112px !important;
    max-height: 58px !important;
}
.segunda-logos img:first-child {
    background: #fff !important;
    padding: 6px !important;
    box-sizing: border-box !important;
}

/* Las tres hojas son las únicas unidades de paginación */
.page-break {
    display: none !important;
}
.segunda-hoja,
.tercera-hoja {
    box-sizing: border-box !important;
    min-height: 0 !important;
    overflow: visible !important;
    position: relative !important;
}

/* Segunda hoja: compacta para que efectivo/transferencia y las
   cuentas queden en UNA sola página */
.segunda-hoja {
    padding: 24px 50px 14px !important;
}
.segunda-hoja .segunda-header {
    padding-bottom: 8px !important;
}
.segunda-hoja .segunda-header strong {
    font-size: 19px !important;
}
.segunda-hoja .segunda-header span {
    font-size: 9px !important;
}
.segunda-hoja .segunda-titulo {
    margin: 18px 0 12px !important;
}
.segunda-hoja .segunda-titulo h1 {
    font-size: 23px !important;
}
.segunda-hoja .segunda-titulo p {
    font-size: 10px !important;
}
.segunda-hoja .seccion-titulo {
    margin: 12px 0 8px !important;
    padding-bottom: 7px !important;
    gap: 9px !important;
}
.segunda-hoja .seccion-titulo > span {
