    if(!select||!idInput||!nombre||!telefono) return;
    select.addEventListener('change',()=>{
        const op=select.options[select.selectedIndex];
        rellenando=true;
        idInput.value=op?.value||'';
        if(op?.value){nombre.value=op.dataset.nombre||'';telefono.value=op.dataset.telefono||'';}
        rellenando=false;
    });
    [nombre,telefono].forEach(el=>el.addEventListener('input',()=>{if(!rellenando){idInput.value='';select.value='';}}));
    function mostrar(){
        if(!modal)return; msg.textContent=''; msg.className='cliente-modal-msg';
        nuevoNombre.value=nombre.value||''; nuevoTelefono.value=telefono.value||'';
        modal.classList.add('open');modal.setAttribute('aria-hidden','false');setTimeout(()=>nuevoNombre.focus(),50);
    }
    function ocultar(){if(!modal)return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');}
    abrir?.addEventListener('click',mostrar); cerrar?.addEventListener('click',ocultar); cancelar?.addEventListener('click',ocultar);
    modal?.addEventListener('click',e=>{if(e.target===modal)ocultar();});
    guardar?.addEventListener('click',async()=>{
        const n=nuevoNombre.value.trim(), t=nuevoTelefono.value.trim();
        if(!n||!t){msg.textContent='Escribe nombre y teléfono.';msg.className='cliente-modal-msg error';return;}
        guardar.disabled=true;msg.textContent='Guardando…';msg.className='cliente-modal-msg';
        try{
            const fd=new FormData();fd.append('nombre',n);fd.append('telefono',t);
            const r=await fetch('cliente_api.php',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}});
            const data=await r.json();
            if(!r.ok||!data.ok)throw new Error(data.error||'No se pudo guardar');
            let op=Array.from(select.options).find(x=>String(x.value)===String(data.cliente.id));
            if(!op){op=document.createElement('option');select.appendChild(op);}
            op.value=data.cliente.id;op.dataset.nombre=data.cliente.nombre;op.dataset.telefono=data.cliente.telefono;op.textContent=data.cliente.nombre+' · '+data.cliente.telefono;
            select.value=String(data.cliente.id);rellenando=true;idInput.value=data.cliente.id;nombre.value=data.cliente.nombre;telefono.value=data.cliente.telefono;rellenando=false;
            ocultar();
        }catch(e){msg.textContent=e.message||'No se pudo guardar el cliente.';msg.className='cliente-modal-msg error';}
        finally{guardar.disabled=false;}
    });
})();


/* ==========================================================
   ANTICIPO EN EL FORMULARIO
   - Cada participante puede activarse/desactivarse.
   - La distribución siempre ocupa el 100% del anticipo.
   - Al editar una persona, su monto queda fijo y la diferencia
     se compensa entre los demás activos según su proporción actual.
   - El campo que se está escribiendo nunca se sobrescribe durante input.
   ========================================================== */
(function () {
    const form = document.querySelector('.form-wrap form[method="POST"]');
    const input = document.getElementById('anticipo-valor');
    const label = document.getElementById('anticipo-valor-label');
    const out = document.getElementById('anticipo-preview-form');
    const conservarRecibido = document.getElementById('conservar-anticipo-recibido');
    const recibidoInput = document.getElementById('anticipo-recibido-monto');
    const recibidoCampos = document.getElementById('anticipo-recibido-campos');
    const recibidoComparacion = document.getElementById('anticipo-recibido-comparacion');
    const usarCalculado = document.getElementById('usar-anticipo-calculado');
    const dividir = document.getElementById('dividir-anticipo');
    const repartirIgual = document.getElementById('repartir-igual');
    const campos = document.getElementById('division-anticipo-campos');
    const estado = document.getElementById('division-anticipo-estado');
    const personas = [
        {key:'sergio', check:document.getElementById('participa-sergio'), input:document.getElementById('anticipo-sergio'), pct:document.getElementById('anticipo-sergio-pct')},
        {key:'ricardo', check:document.getElementById('participa-ricardo'), input:document.getElementById('anticipo-ricardo'), pct:document.getElementById('anticipo-ricardo-pct')},
        {key:'tomas', check:document.getElementById('participa-tomas'), input:document.getElementById('anticipo-tomas'), pct:document.getElementById('anticipo-tomas-pct')}
    ];
    if (!form || !input || !label || !out) return;

    let ajustando = false;
    let ultimoEditado = null;
    let ultimoAnticipo = null;
    const money = n => Number(n || 0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
    const cents = n => Math.round((Number(n) || 0) * 100) / 100;

    function subtotalOperacion(){
        let t=0;
        const qs=form.querySelectorAll('input[name="cantidad[]"]');
        const ps=form.querySelectorAll('input[name="precio[]"]');
        for(let i=0;i<Math.max(qs.length,ps.length);i++){
            const q=parseFloat(qs[i]?.value||0), p=parseFloat(ps[i]?.value||0);
            if(q>0&&p>=0)t+=q*p;
        }
        return cents(t);
    }

    function totalOperacion(){
        const subtotal=subtotalOperacion();
        const factura=form.querySelector('input[name="requiere_factura"]:checked')?.value==='si';
        return cents(subtotal*(factura?1.16:1));
    }

    function anticipo(){
        const subtotal=subtotalOperacion();
        const factura=form.querySelector('input[name="requiere_factura"]:checked')?.value==='si';
        const total=cents(subtotal*(factura?1.16:1));
        // El IVA nunca entra al adelanto: la base del anticipo es siempre el subtotal.
        const baseAnticipo=subtotal;
        const tipo=form.querySelector('input[name="anticipo_tipo"]:checked')?.value||'porcentaje';
        let v=parseFloat(input.value||0), teorico=0, teoricoPct=0;
        if(tipo==='monto'){
            label.textContent='Monto del anticipo calculado ($):';
            input.max=baseAnticipo.toFixed(2);
            teorico=Math.max(0,Math.min(baseAnticipo,v));
            teoricoPct=baseAnticipo>0?teorico/baseAnticipo*100:0;
        } else {
            label.textContent='Porcentaje de anticipo calculado (%):';
            input.max='100';
            teoricoPct=Math.max(0,Math.min(100,v));
            teorico=baseAnticipo*teoricoPct/100;
        }
        teorico=cents(teorico);
        const congelado=!!conservarRecibido?.checked;
        let monto=congelado?Math.max(0,cents(parseFloat(recibidoInput?.value||0))):teorico;
        let pct=baseAnticipo>0?monto/baseAnticipo*100:0;
        return {total,subtotal,baseAnticipo,factura,monto:cents(monto),pct,teorico,teoricoPct,congelado};
    }

    function activos(){ return personas.filter(p=>p.check?.checked); }
    function valor(p){ return Math.max(0,cents(parseFloat(p.input?.value||0))); }
    function setValor(p,v){ if(p.input) p.input.value=Math.max(0,cents(v)).toFixed(2); }

    function repartoConceptosInterno(){
        const totales={sergio:0,ricardo:0,tomas:0,sinAsignar:0};
        const filas=form.querySelectorAll('#tabla-conceptos tr');
        filas.forEach(fila=>{
            const q=parseFloat(fila.querySelector('input[name="cantidad[]"]')?.value||0);
            const p=parseFloat(fila.querySelector('input[name="precio[]"]')?.value||0);
            if(!(q>0) || !(p>=0)) return;
            const totalCentavos=Math.round(q*p*100);
            if(totalCentavos<=0) return;
            const resp=Array.from(fila.querySelectorAll('.responsable-check:checked')).map(x=>x.value).filter(x=>['sergio','ricardo','tomas'].includes(x));
            if(!resp.length){
                totales.sinAsignar=cents(totales.sinAsignar+totalCentavos/100);
                return;
            }
            const base=Math.floor(totalCentavos/resp.length);
            const resto=totalCentavos-(base*resp.length);
            resp.forEach((r,i)=>{
                const parte=base+(i===resp.length-1?resto:0);
                totales[r]=cents(totales[r]+parte/100);
            });
        });
        return totales;
    }

    function renderResumenInterno(a){
        const box=document.getElementById('resumen-interno-form');
        if(!box) return;
        const reparto=repartoConceptosInterno();
        const recibidos={
            sergio:(dividir?.checked && personas[0].check?.checked)?valor(personas[0]):0,
            ricardo:(dividir?.checked && personas[1].check?.checked)?valor(personas[1]):0,
            tomas:(dividir?.checked && personas[2].check?.checked)?valor(personas[2]):0
        };
        ['sergio','ricardo','tomas'].forEach(k=>{
            const card=box.querySelector('[data-interno-persona="'+k+'"]');
            if(!card) return;
            const corresponde=cents(reparto[k]);
            const recibido=cents(recibidos[k]);
            const restante=cents(Math.max(0,corresponde-recibido));
            const excedente=cents(Math.max(0,recibido-corresponde));
            card.querySelector('.interno-corresponde').textContent='$'+money(corresponde);
            card.querySelector('.interno-anticipo').textContent='$'+money(recibido);
            card.querySelector('.interno-restante').textContent='$'+money(restante);
            const linea=card.querySelector('.interno-excedente-linea');
            if(linea){
                linea.style.display=excedente>0.009?'flex':'none';
                card.querySelector('.interno-excedente').textContent='$'+money(excedente);
            }
        });

        const iva=cents(a.factura?a.subtotal*0.16:0);
        const ivaCard=box.querySelector('[data-interno-persona="iva"]');
        if(ivaCard){
            ivaCard.style.display=a.factura?'block':'none';
            ivaCard.querySelector('.interno-corresponde').textContent='$'+money(iva);
            ivaCard.querySelector('.interno-anticipo').textContent='$0.00';
            ivaCard.querySelector('.interno-restante').textContent='$'+money(iva);
        }
        const saldoActual=cents(Math.max(0,a.total-a.monto));
        const diferencia=cents(a.teorico-a.monto);
        const teoricoEl=document.getElementById('interno-anticipo-teorico');
        const realEl=document.getElementById('interno-anticipo-real');
        const difEl=document.getElementById('interno-anticipo-diferencia');
        const saldoEl=document.getElementById('interno-saldo-actual');
        if(teoricoEl) teoricoEl.textContent='$'+money(a.teorico);
        if(realEl) realEl.textContent='$'+money(a.monto)+(a.congelado?' · FIJO':'');
        if(difEl){
            difEl.textContent=(diferencia>=0?'$'+money(diferencia):'-$'+money(Math.abs(diferencia)));
            difEl.style.color=diferencia>0.009?'#9a5b00':(diferencia<-0.009?'#287a3d':'');
        }
        if(saldoEl) saldoEl.textContent='$'+money(saldoActual);

        const alerta=document.getElementById('resumen-interno-sin-asignar');
        if(alerta){
            const avisos=[];
            if(reparto.sinAsignar>0.009) avisos.push('Conceptos sin responsable asignado: $'+money(reparto.sinAsignar)+'. Asígnalos a Sergio, Ricardo o Tomás para incluirlos en el saldo individual.');
            if(!dividir?.checked) avisos.push('El anticipo todavía no está distribuido por integrante; el resumen no descuenta adelantos individuales.');
            alerta.style.display=avisos.length?'block':'none';
            alerta.textContent=avisos.join(' ');
        }
    }

    // Distribuye un total entre una lista conservando las proporciones actuales.
    // Si todos están en cero, el primero absorbe el total: nunca se inventan partes iguales.
    function distribuirProporcional(lista,total){
        total=Math.max(0,cents(total));
        if(!lista.length) return;
        if(lista.length===1){ setValor(lista[0],total); return; }
        const pesos=lista.map(valor);
        const suma=cents(pesos.reduce((a,b)=>a+b,0));
        if(suma<=0){
            setValor(lista[0],total);
            lista.slice(1).forEach(p=>setValor(p,0));
            return;
        }
        let asignado=0;
        lista.forEach((p,i)=>{
            let v;
            if(i===lista.length-1) v=cents(total-asignado);
            else v=Math.floor((total*(pesos[i]/suma))*100)/100;
            setValor(p,v);
            asignado=cents(asignado+v);
        });
    }

    // Reparte exactamente por igual entre los participantes activos.
    // El último recibe cualquier centavo residual para cerrar al 100%.
    function distribuirIgual(lista,total){
        total=Math.max(0,cents(total));
        if(!lista.length) return;
        const totalCentavos=Math.round(total*100);
        const base=Math.floor(totalCentavos/lista.length);
        const resto=totalCentavos-(base*lista.length);
        lista.forEach((p,i)=>{
            const centavos=base+(i===lista.length-1?resto:0);
            setValor(p,centavos/100);
        });
    }

    function aplicarRepartoIgual(monto){
        const a=activos();
        personas.filter(p=>!p.check?.checked).forEach(p=>setValor(p,0));
        if(!a.length) return;
        distribuirIgual(a,monto);
    }

    // Mantiene fijo el monto que el usuario está escribiendo y hace que
    // los demás participantes activos absorban exactamente la diferencia.
    // IMPORTANTE: durante el evento input NO se reescribe el campo editado,
    // así el usuario puede borrar, seleccionar y teclear una cantidad nueva
    // sin que el sistema "pelee" con el teclado.
    function ajustarDesde(editado,monto,normalizarEditado=false){
        const a=activos();
        personas.filter(p=>!p.check?.checked).forEach(p=>setValor(p,0));
        if(!a.length) return;

        if(!editado || !editado.check.checked){
            distribuirProporcional(a,monto);
            return;
        }

        let escrito=parseFloat(editado.input?.value);
        if(!Number.isFinite(escrito)) escrito=0;
        let fijo=Math.max(0,cents(escrito));

        // Mientras se escribe dejamos intacto el texto del campo. Al confirmar
        // (change/blur) sí normalizamos límites y formato monetario.
        if(fijo>monto) fijo=cents(monto);
        if(normalizarEditado) setValor(editado,fijo);

        const otros=a.filter(p=>p!==editado);
        if(!otros.length){
            if(normalizarEditado) setValor(editado,monto);
            return;
        }
        distribuirProporcional(otros,cents(monto-fijo));
    }

    // Cuando cambia el anticipo total, escala la distribución existente
    // conservando el porcentaje relativo de cada participante activo.
    function ajustarNuevoTotal(monto){
        const a=activos();
        personas.filter(p=>!p.check?.checked).forEach(p=>setValor(p,0));
        if(!a.length) return;
        distribuirProporcional(a,monto);
    }

    function render(){
        const a=anticipo(), saldo=Math.max(0,a.total-a.monto), sp=a.total>0?saldo/a.total*100:0;
        if(recibidoCampos) recibidoCampos.style.display=a.congelado?'grid':'none';
        if(recibidoComparacion){
            recibidoComparacion.style.display=a.congelado?'block':'none';
            const dif=cents(a.teorico-a.monto);
            recibidoComparacion.innerHTML='<strong>Anticipo calculado actual:</strong> $'+money(a.teorico)+' · <strong>Ya recibido:</strong> $'+money(a.monto)+' ('+a.pct.toFixed(2)+'% del subtotal) · <strong>'+(dif>=0?'Diferencia pendiente vs. cálculo':'Recibido por encima del cálculo')+':</strong> $'+money(Math.abs(dif))+' · <strong>Saldo total:</strong> $'+money(saldo)+(a.factura?' · IVA completo fuera del anticipo':'');
        }
        out.textContent=a.congelado
            ? 'Anticipo ya recibido y congelado: $'+money(a.monto)+' ('+a.pct.toFixed(2)+'% del subtotal) · El cálculo actual sería $'+money(a.teorico)+' · Saldo total pendiente $'+money(saldo)+(a.factura?' · IVA fuera del anticipo':'')
            : (a.factura
                ? 'Resultado: '+a.pct.toFixed(2)+'% del subtotal = $'+money(a.monto)+' · IVA fuera del anticipo · Saldo total pendiente $'+money(saldo)
                : 'Resultado: '+a.pct.toFixed(2)+'% = $'+money(a.monto)+' · Saldo '+sp.toFixed(2)+'% = $'+money(saldo));
        renderResumenInterno(a);
        if(!dividir || !campos || !estado) return;
        campos.style.display=dividir.checked?'grid':'none';
        if(!dividir.checked){ estado.textContent=''; return; }

        let ac=activos();
        if(!ac.length){
            if(personas[0].check) personas[0].check.checked=true;
            ac=activos();
            setValor(personas[0],a.monto);
        }
        personas.forEach(p=>{
            if(p.input){
                p.input.disabled=!p.check.checked;
                p.input.readOnly=!!(p.check.checked && repartirIgual?.checked);
                p.input.style.opacity=p.check.checked?'1':'.45';
                p.input.style.backgroundColor=(p.check.checked && repartirIgual?.checked)?'#f2f4f7':'';
                p.input.title=(p.check.checked && repartirIgual?.checked)?'Desactiva Repartir por igual para editar manualmente esta cantidad.':'';
            }
        });
        const suma=cents(ac.reduce((t,p)=>t+valor(p),0));
        personas.forEach(p=>{
            const v=p.check.checked?valor(p):0;
            if(p.pct) p.pct.textContent=p.check.checked?((a.monto>0?v/a.monto*100:0).toFixed(2)+'% del anticipo'):'No participa';
        });
        estado.textContent='Total distribuido: $'+money(suma)+' = '+(a.monto>0?suma/a.monto*100:0).toFixed(2)+'% del anticipo.';
        estado.style.color=Math.abs(suma-a.monto)<=0.01?'#287a3d':'#a33';
    }

    function update(tipo='render'){
        if(ajustando) return;
        ajustando=true;
        const a=anticipo();
        if(dividir?.checked){
            if(repartirIgual?.checked) aplicarRepartoIgual(a.monto);
            else if(tipo==='edit' && ultimoEditado) ajustarDesde(ultimoEditado,a.monto,false);
            else if(tipo==='edit-final' && ultimoEditado) ajustarDesde(ultimoEditado,a.monto,true);
            else if(tipo==='total') ajustarNuevoTotal(a.monto);
        }
        ultimoAnticipo=a.monto;
        render();
        ajustando=false;
    }

    window.actualizarResumenInterno = function(){ render(); };

    conservarRecibido?.addEventListener('change',()=>{
        // Al activar por primera vez, congelar exactamente el anticipo calculado en ese momento.
        if(conservarRecibido.checked && recibidoInput){
            const a=anticipo();
            const actual=parseFloat(recibidoInput.value||0);
            if(!(actual>0)) recibidoInput.value=a.teorico.toFixed(2);
        }
        ultimoEditado=null;
        update('total');
    });
    recibidoInput?.addEventListener('input',()=>{
        if(!conservarRecibido?.checked) return;
        ultimoEditado=null;
        update('total');
    });
    recibidoInput?.addEventListener('change',()=>{
        if(recibidoInput) recibidoInput.value=Math.max(0,cents(parseFloat(recibidoInput.value||0))).toFixed(2);
        ultimoEditado=null;
        update('total');
    });
    usarCalculado?.addEventListener('click',()=>{
        const a=anticipo();
        if(recibidoInput) recibidoInput.value=a.teorico.toFixed(2);
        if(conservarRecibido) conservarRecibido.checked=true;
        ultimoEditado=null;
        update('total');
    });

    personas.forEach(p=>{
        // Ajuste en tiempo real de LOS OTROS campos. El campo que se está
        // tecleando no se modifica hasta que el usuario confirme/salga de él.
        p.input?.addEventListener('input',()=>{
            ultimoEditado=p;
            update('edit');
        });
        p.input?.addEventListener('change',()=>{
            ultimoEditado=p;
            update('edit-final');
        });
        p.check?.addEventListener('change',()=>{
            if(ajustando) return;
            ajustando=true;
            const a=anticipo();
            if(p.check.checked){
                // Un participante nuevo entra en $0 en modo manual.
                setValor(p,0);
                const ac=activos();
                if(repartirIgual?.checked) aplicarRepartoIgual(a.monto);
                else if(ac.length===1) setValor(p,a.monto);
                else ajustarNuevoTotal(a.monto);
            } else {
                setValor(p,0);
                let ac=activos();
                if(!ac.length){
                    personas[0].check.checked=true;
                    ac=activos();
                }
                // En modo igual se recalculan partes iguales; en manual se conserva la proporción previa.
                if(repartirIgual?.checked) aplicarRepartoIgual(a.monto);
                else distribuirProporcional(ac,a.monto);
            }
            ultimoEditado=null;
            ultimoAnticipo=a.monto;
            render();
            ajustando=false;
        });
    });

    dividir?.addEventListener('change',()=>{
        if(!dividir.checked){ render(); return; }
        const a=anticipo();
        let ac=activos();
        if(!ac.length){ personas[0].check.checked=true; ac=activos(); }
        if(repartirIgual?.checked) aplicarRepartoIgual(a.monto);
        else ajustarNuevoTotal(a.monto);
        ultimoAnticipo=a.monto;
        render();
    });

    repartirIgual?.addEventListener('change',()=>{
        if(!dividir?.checked) return;
        const a=anticipo();
        let ac=activos();
        if(!ac.length){ personas[0].check.checked=true; ac=activos(); }
        if(repartirIgual.checked) aplicarRepartoIgual(a.monto);
        // Al desactivarlo se conservan los importes actuales y vuelven a ser editables.
        ultimoEditado=null;
        ultimoAnticipo=a.monto;
        render();
    });

    form.addEventListener('input',e=>{
        if(e.target.matches('input[name="anticipo_tipo"],#anticipo-valor,input[name="cantidad[]"],input[name="precio[]"],input[name="requiere_factura"]')){
            ultimoEditado=null;
            update('total');
        }
    });
    form.addEventListener('change',e=>{
        if(e.target.matches('input[name="anticipo_tipo"],input[name="requiere_factura"]')){
            ultimoEditado=null;
            update('total');
        }
    });

    form.addEventListener('submit',e=>{
        if(dividir?.checked){
            const a=anticipo(), ac=activos(), suma=cents(ac.reduce((t,p)=>t+valor(p),0));
            if(!ac.length || Math.abs(suma-a.monto)>0.01){
                e.preventDefault();
                estado.textContent='La distribución debe completar exactamente el 100% del anticipo.';
                estado.style.color='#a33';
                estado.scrollIntoView({behavior:'smooth',block:'center'});
            }
        }
    });

    // Al abrir una cotización existente, conserva sus proporciones guardadas.
    if(dividir?.checked){
        const a=anticipo();
        let ac=activos();
        if(!ac.length){ personas[0].check.checked=true; ac=activos(); }
        const suma=cents(ac.reduce((t,p)=>t+valor(p),0));
        if(repartirIgual?.checked) aplicarRepartoIgual(a.monto);
        else if(Math.abs(suma-a.monto)>0.01) distribuirProporcional(ac,a.monto);
        ultimoAnticipo=a.monto;
    }
    render();
})();
</script>
<script>
/* MSI automáticos: cada banco se valida por el cobro final de cada operación. */
window.SRNU_PAGOS_REGLAS = <?= json_encode(srnu_tarjeta_reglas(), JSON_UNESCAPED_SLASHES) ?>;
<?php readfile(__DIR__ . '/assets/cotizacion_tarjeta.js'); ?>
(function () {
    const formulario = document.querySelector('.form-wrap form[method="POST"]');
    const pagos = window.SRNU_PAGOS;
    if (!formulario || !document.getElementById('clip-msi-grid')) return;
    const money = n => new Intl.NumberFormat('es-MX', {style:'currency',currency:'MXN'}).format(n);
    let actualizando = false;
    function subtotalActual() {
        let subtotal = 0;
        const cantidades = formulario.querySelectorAll('input[name="cantidad[]"]');
        const precios = formulario.querySelectorAll('input[name="precio[]"]');
        for (let i=0; i<Math.max(cantidades.length,precios.length); i++) {
            const cantidad = parseFloat(cantidades[i]?.value || 0);
            const precio = parseFloat(precios[i]?.value || 0);
            if (cantidad > 0 && precio > 0) subtotal += cantidad * precio;
        }
        return pagos.centavos(subtotal);
    }
    function planes(subtotal, total, banco) {
        const plazos = banco === 'clip' ? pagos.plazosClip(total) : pagos.plazosBBVA(subtotal);
        return plazos.map(plazo => {
            const cobro = banco === 'bbva' ? pagos.bbva(subtotal,plazo) : pagos.clip(total,plazo);
            return '<div class="srnu-msi-plan"><strong>'+plazo+' MSI</strong><span class="srnu-msi-amount">'+(subtotal>0?money(cobro):'—')+'</span><span class="srnu-msi-monthly">'+(subtotal>0?money(cobro/plazo)+' / mes':'Agrega un precio')+'</span></div>';
        }).join('');
    }
    function actualizarMSI() {
        if (actualizando) return;
        actualizando = true;
        try {
            const subtotal = subtotalActual();
            const si = formulario.querySelector('input[name="requiere_factura"][value="si"]');
            const no = formulario.querySelector('input[name="requiere_factura"][value="no"]');
            // BBVA PyME manual: al marcarlo se activa la factura y se bloquea "No requiere"; al desmarcarlo vuelve a ser libre.
            const usarBBVA = !!document.getElementById('bbva-pyme')?.checked;
            if (no) no.disabled = usarBBVA;
            if (usarBBVA && si && !si.checked) {
                si.checked = true;
                si.dispatchEvent(new Event('change',{bubbles:true}));
            }
            const total = pagos.total(subtotal,!!si?.checked);
            document.getElementById('pago-tarjeta-terminal').textContent = usarBBVA ? 'CLIP + BBVA PyME' : 'CLIP';
            document.getElementById('pago-tarjeta-section').dataset.terminal = usarBBVA ? 'clip_bbva' : 'clip';
            document.getElementById('clip-msi-grid').innerHTML = planes(subtotal,total,'clip');
            document.getElementById('bbva-pyme-wrap').hidden = !usarBBVA;
            document.getElementById('bbva-msi-grid').innerHTML = usarBBVA ? planes(subtotal,total,'bbva') : '';
            document.getElementById('bbva-pyme-total').textContent = money(pagos.total(subtotal,true));
            document.getElementById('clip-una-exhibicion').textContent = 'Una sola exhibición Clip: '+(subtotal>0?money(pagos.clip(total,0)):'Agrega un precio para calcular');
            const unaBBVA = usarBBVA && pagos.unaBBVA(subtotal);
            const sinOpcionesBBVA = usarBBVA && subtotal > 0 && !unaBBVA && pagos.plazosBBVA(subtotal).length === 0;
            document.getElementById('bbva-una-exhibicion').hidden = !(unaBBVA || sinOpcionesBBVA);
            document.getElementById('bbva-una-exhibicion').textContent = unaBBVA ? 'Una sola exhibición BBVA: '+money(pagos.bbva(subtotal,0)) : (sinOpcionesBBVA ? 'Con este monto ningún cobro BBVA supera $50,000, por eso no hay opciones BBVA. La factura sí queda activa.' : '');
            document.getElementById('msi-estado').textContent = subtotal<=0 ? 'Agrega un concepto para calcular los MSI.' : usarBBVA ? 'Clip se conserva. BBVA PyME solo muestra cobros mayores a $50,000 con comisión y factura obligatoria.' : pagos.plazosClip(total).length ? 'Una exhibición y MSI disponibles incluidos automáticamente.' : 'Pago con tarjeta a una sola exhibición incluido.';
        } finally { actualizando = false; }
    }
    formulario.addEventListener('input',actualizarMSI);
    formulario.addEventListener('change',actualizarMSI);
    formulario.addEventListener('submit',actualizarMSI);
    window.srnuActualizarMSI = actualizarMSI;
    const tabla = document.getElementById('tabla-conceptos');
    if (tabla) new MutationObserver(actualizarMSI).observe(tabla,{childList:true});
    window.addEventListener('pageshow',actualizarMSI);
    actualizarMSI();
})();
</script>
<script>
function actualizarResponsablesFila(elemento) {
    const fila = elemento.closest('tr');
    if (!fila) return;
    const oculto = fila.querySelector('.responsables-hidden');
    if (!oculto) return;
    const seleccionados = Array.from(fila.querySelectorAll('.responsable-check:checked')).map(input => input.value);
    oculto.value = seleccionados.join(',');
}

document.addEventListener('change', function (event) {
    if (event.target.classList && event.target.classList.contains('responsable-check')) {
        actualizarResponsablesFila(event.target);
        if (typeof window.actualizarResumenInterno === 'function') window.actualizarResumenInterno();
    }
});

document.querySelector('form')?.addEventListener('submit', function () {
    document.querySelectorAll('#tabla-conceptos tr').forEach(fila => {
        const check = fila.querySelector('.responsable-check');
        if (check) actualizarResponsablesFila(check);
    });
});

function agregarFila(datos = null) {

    const tabla =
        document.getElementById(
            'tabla-conceptos'
        );


    const fila =
        document.createElement('tr');


    fila.innerHTML = `

        <td>
            <input
                type="text"
                name="concepto[]"
            >
        </td>

        <td>
            <input
                type="number"
                name="cantidad[]"
                min="1"
            >
        </td>

        <td>
            <input
                type="number"
                step="0.01"
                name="precio[]"
            >
        </td>

        <td>
            <input type="number" step="0.01" min="0" name="costo_interno[]" title="Solo uso interno">
            <input type="hidden" name="catalogo_id[]" value="0">
        </td>
        <td>
            <input type="number" min="0" max="120" name="garantia_meses[]" value="0" title="Sobre pedido: 12 meses de garantía por defecto.">
        </td>
        <td>
            <select name="tipo_entrega[]" class="tipo-entrega-item" onchange="actualizarDiasEntregaFila(this)">
                <option value="inmediata">Entrega inmediata</option>
                <option value="sobre_pedido">Sobre pedido</option>
            </select>
            <input type="number" min="0" max="365" name="dias_entrega_estimada[]" value="0" class="dias-entrega-item" placeholder="Días llegada" style="display:none;margin-top:6px">
        </td>
        <td class="foto-producto-cell">
            <input type="hidden" name="foto_producto_actual[]" class="foto-producto-actual" value="">
            <input type="hidden" name="mostrar_foto_pdf[]" class="mostrar-foto-pdf-hidden" value="1">
            <input type="hidden" name="quitar_foto[]" class="quitar-foto-hidden" value="0">
            <div class="foto-producto-preview-wrap" style="display:none"><img class="foto-producto-preview" src="" alt="Foto producto"></div>
            <input type="file" name="foto_producto[]" class="foto-producto-input" accept="image/jpeg,image/png,image/webp">
            <label class="foto-pdf-check"><input type="checkbox" class="mostrar-foto-pdf-check" checked> Mostrar en PDF</label>
            <button type="button" class="btn-foto-quitar" onclick="quitarFotoProducto(this)" style="display:none">Quitar foto</button>
        </td>
        <td>
            <div class="responsables-servicio">
                <label><input type="checkbox" class="responsable-check" value="sergio"> Sergio</label>
                <label><input type="checkbox" class="responsable-check" value="ricardo"> Ricardo</label>
                <label><input type="checkbox" class="responsable-check" value="tomas"> Tomás</label>
                <input type="hidden" name="responsables[]" class="responsables-hidden" value="">
            </div>
        </td>

        <td>
            <button
                type="button"
                class="btn-quitar"
                onclick="quitarFila(this)"
            >
                ✕
            </button>
        </td>

    `;


    tabla.appendChild(fila);
    if (datos) {
        fila.querySelector('input[name="concepto[]"]').value = (datos.nombre || '') + (datos.descripcion ? ' — ' + datos.descripcion : '');
        fila.querySelector('input[name="cantidad[]"]').value = '1';
        fila.querySelector('input[name="precio[]"]').value = Number(datos.precio_base || 0).toFixed(2);
        fila.querySelector('input[name="costo_interno[]"]').value = Number(datos.costo_base || 0).toFixed(2);
        fila.querySelector('input[name="garantia_meses[]"]').value = parseInt(datos.garantia_meses || 0,10);
        fila.querySelector('input[name="catalogo_id[]"]').value = datos.id || 0;
        const te = fila.querySelector('select[name="tipo_entrega[]"]'); if (te) { te.value = datos.tipo_entrega || 'inmediata'; actualizarDiasEntregaFila(te); }
        const de = fila.querySelector('input[name="dias_entrega_estimada[]"]'); if (de) de.value = parseInt(datos.dias_entrega_estimada || 0,10);
        if (datos.foto_producto) {
            const hid=fila.querySelector('.foto-producto-actual'), img=fila.querySelector('.foto-producto-preview'), wrap=fila.querySelector('.foto-producto-preview-wrap'), rm=fila.querySelector('.btn-foto-quitar');
            if(hid) hid.value=datos.foto_producto; if(img) img.src=datos.foto_producto; if(wrap) wrap.style.display=''; if(rm) rm.style.display='';
        }
        ['sergio','ricardo','tomas'].forEach(k => {
            const ch = fila.querySelector('.responsable-check[value="'+k+'"]');
            if (ch) ch.checked = !!Number(datos['responsable_'+k] || 0);
        });
        const ch = fila.querySelector('.responsable-check'); if (ch) actualizarResponsablesFila(ch);
    }
    if (typeof window.actualizarResumenInterno === 'function') window.actualizarResumenInterno();
    if (typeof window.srnuActualizarMSI === 'function') window.srnuActualizarMSI();

    fila.querySelector('input[name="concepto[]"]').focus();

}


function sincronizarMostrarFotoPdf(fila){
    if(!fila)return; const ch=fila.querySelector('.mostrar-foto-pdf-check'), hid=fila.querySelector('.mostrar-foto-pdf-hidden'); if(ch&&hid)hid.value=ch.checked?'1':'0';
}
function quitarFotoProducto(btn){
    const fila=btn.closest('tr'); if(!fila)return; const actual=fila.querySelector('.foto-producto-actual'), quitar=fila.querySelector('.quitar-foto-hidden'), input=fila.querySelector('.foto-producto-input'), wrap=fila.querySelector('.foto-producto-preview-wrap'), img=fila.querySelector('.foto-producto-preview');
    if(actual)actual.value=''; if(quitar)quitar.value='1'; if(input)input.value=''; if(img)img.src=''; if(wrap)wrap.style.display='none'; btn.style.display='none';
}
document.addEventListener('change',function(e){
    if(e.target.classList&&e.target.classList.contains('mostrar-foto-pdf-check')) sincronizarMostrarFotoPdf(e.target.closest('tr'));
    if(e.target.classList&&e.target.classList.contains('foto-producto-input')){
        const fila=e.target.closest('tr'); if(!fila||!e.target.files||!e.target.files[0])return; const f=e.target.files[0]; if(!f.type.startsWith('image/'))return;
        const img=fila.querySelector('.foto-producto-preview'), wrap=fila.querySelector('.foto-producto-preview-wrap'), rm=fila.querySelector('.btn-foto-quitar'), quitar=fila.querySelector('.quitar-foto-hidden');
        if(img)img.src=URL.createObjectURL(f); if(wrap)wrap.style.display=''; if(rm)rm.style.display=''; if(quitar)quitar.value='0';
    }
});

function actualizarDiasEntregaFila(select) {
    const fila = select.closest('tr');
    if (!fila) return;
    const campo = fila.querySelector('input[name="dias_entrega_estimada[]"]');
    const garantia = fila.querySelector('input[name="garantia_meses[]"]');
    const sobrePedido = select.value === 'sobre_pedido';

    if (campo) {
        campo.style.display = sobrePedido ? '' : 'none';
        if (!sobrePedido) campo.value = '0';
    }

    // Política SRNU: servicios sobre pedido tienen 12 meses de garantía por defecto.
    // Solo se autocompleta cuando todavía no existe un plazo definido; si el usuario
    // captura manualmente otro valor, se respeta.
    if (sobrePedido && garantia) {
        const meses = parseInt(garantia.value || '0', 10);
        if (!Number.isFinite(meses) || meses <= 0) garantia.value = '12';
    }
}


function escapeHtmlRec(v){return String(v??'').replace(/[&<>\'\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));}
function abrirIAAftermarket(){
    const drawer=document.getElementById('ia-aftermarket-drawer'), overlay=document.getElementById('ia-aftermarket-overlay');
    if(drawer)drawer.classList.add('open'); if(overlay)overlay.classList.add('open');
    investigarAftermarket();
}
function cerrarIAAftermarket(){document.getElementById('ia-aftermarket-drawer')?.classList.remove('open');document.getElementById('ia-aftermarket-overlay')?.classList.remove('open');}

function estadoAsesorPrecio(){return localStorage.getItem('srnu_ia_price_panel_state')||'expanded';}
function aplicarEstadoAsesorPrecio(estado=null){
    estado=estado||estadoAsesorPrecio();
    if(!['expanded','minimized','hidden'].includes(estado))estado='expanded';
    const panel=document.getElementById('ia-price-live'), reopen=document.getElementById('ia-price-reopen');
    const minBtn=document.getElementById('ia-price-min-btn'), expBtn=document.getElementById('ia-price-expand-btn');
    if(!panel)return;
    panel.classList.toggle('minimized',estado==='minimized');
    panel.classList.toggle('hidden-by-user',estado==='hidden');
    if(reopen)reopen.style.display=estado==='hidden'?'flex':'none';
    if(minBtn)minBtn.style.display=estado==='minimized'?'none':'inline-flex';
    if(expBtn)expBtn.style.display=estado==='expanded'?'none':'inline-flex';
}
function minimizarAsesorPrecio(){localStorage.setItem('srnu_ia_price_panel_state','minimized');aplicarEstadoAsesorPrecio('minimized');}
function expandirAsesorPrecio(){localStorage.setItem('srnu_ia_price_panel_state','expanded');aplicarEstadoAsesorPrecio('expanded');}
function ocultarAsesorPrecio(){localStorage.setItem('srnu_ia_price_panel_state','hidden');aplicarEstadoAsesorPrecio('hidden');}
function mostrarAsesorPrecio(){localStorage.setItem('srnu_ia_price_panel_state','expanded');aplicarEstadoAsesorPrecio('expanded');}
function actualizarResumenCompactoPrecio(d=null){
    const el=document.getElementById('ia-price-compact');if(!el)return;
    const a=d?.analisis||iaPrecioUltimoResultado?.analisis||{};
    if(!a||!a.clasificacion){el.textContent='Listo para analizar';el.className='ia-price-compact';return;}
    const objetivo=Number(a.precio_objetivo||0);
    el.textContent=iaPrecioClasificacionTexto(a.clasificacion||'sin_datos')+(objetivo>0?' · Objetivo '+iaMoney(objetivo):'');
    el.className='ia-price-compact '+iaPrecioClasificacionClase(a.clasificacion||'sin_datos');
}
function iaAftermarketLink(url,label,cls=''){
    if(!url)return '';return '<a class="ia-am-link '+cls+'" href="'+escapeHtmlRec(url)+'" target="_blank" rel="noopener noreferrer">'+escapeHtmlRec(label)+'</a>';
}
function iaAftermarketBadge(text,kind='') { return '<span class="ia-am-badge '+kind+'">'+escapeHtmlRec(text)+'</span>'; }
async function investigarAftermarket(){
    const veh=(document.getElementById('vehiculo-input')?.value||'').trim();
    const body=document.getElementById('ia-aftermarket-body'), title=document.getElementById('ia-aftermarket-vehicle');
    if(title)title.textContent=veh||'Vehículo sin capturar';
    if(!body)return;
    if(!veh){body.innerHTML='<div class="ia-am-empty"><b>Escribe primero el vehículo.</b><br>Ejemplo: Toyota Tacoma 2025, Jetta GLI 2022 o RAM 1200 2026.</div>';return;}
    const existentes=Array.from(document.querySelectorAll('input[name="concepto[]"]')).map(x=>x.value).filter(Boolean);
    body.innerHTML='<div class="ia-am-loading"><div class="ia-am-spinner"></div><b>Investigando '+escapeHtmlRec(veh)+'…</b><span>Historial SRNU + tendencias web + catálogo + IA local.</span></div>';
    try{
        const fd=new FormData(); fd.append('vehiculo',veh); fd.append('existentes',JSON.stringify(existentes));
        const res=await fetch('aftermarket_ia.php',{method:'POST',body:fd}); const d=await res.json(); if(!d.ok)throw new Error(d.error||'No se pudo investigar el vehículo');
        let html='';
        html+='<section class="ia-am-section"><div class="ia-am-section-title">Resumen inteligente '+iaAftermarketBadge(d.motor||'LOCAL','blue')+'</div><p class="ia-am-summary">'+escapeHtmlRec(d.resumen||'')+'</p></section>';
        const h=d.historial||{};
        html+='<section class="ia-am-section"><div class="ia-am-section-title">Historial SRNU</div>';
        html+='<div class="ia-am-statrow"><div><b>'+Number(h.vehiculos_similares||0)+'</b><span>vehículos similares</span></div><div><b>'+Number(h.cotizaciones||0)+'</b><span>cotizaciones relacionadas</span></div></div>';
        const hs=Array.isArray(h.servicios)?h.servicios:[];
        if(hs.length){html+='<div class="ia-am-history">';hs.slice(0,8).forEach(x=>{html+='<div><span>'+escapeHtmlRec(x.concepto||'Servicio')+'</span><b>'+Number(x.veces||0)+'×</b></div>';});html+='</div>';}else html+='<div class="ia-am-muted">Todavía no hay suficiente historial de este vehículo en SRNU.</div>';
        const hc=Array.isArray(h.clientes)?h.clientes:[];if(hc.length){html+='<div class="ia-am-mini-title">Clientes con vehículo similar</div><div class="ia-am-clients">';hc.forEach(c=>{html+='<a href="'+escapeHtmlRec(c.url||'#')+'"><b>'+escapeHtmlRec(c.cliente||'Cliente')+'</b><span>'+escapeHtmlRec((c.vehiculo||'')+' · '+(c.folio||''))+'</span>'+(Array.isArray(c.servicios)&&c.servicios.length?'<small>'+escapeHtmlRec(c.servicios.join(' · '))+'</small>':'')+'</a>';});html+='</div>';}
        html+='</section>';
        const recs=Array.isArray(d.recomendaciones)?d.recomendaciones:[];
        html+='<section class="ia-am-section"><div class="ia-am-section-title">Servicios que puedes ofrecer</div>';
        if(!recs.length) html+='<div class="ia-am-muted">No encontré recomendaciones claras del catálogo.</div>';
        else recs.forEach((r,i)=>{const s=r.servicio||{};html+='<article class="ia-am-card"><div class="ia-am-cardtop"><div><b>'+escapeHtmlRec(s.nombre||'Servicio')+'</b><div>'+iaAftermarketBadge((r.prioridad||'media').toUpperCase(),r.prioridad==='alta'?'red':'')+' '+iaAftermarketBadge(r.fuente||'Catálogo SRNU','')+'</div></div><strong>$'+Number(s.precio_base||0).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2})+'</strong></div><p>'+escapeHtmlRec(r.motivo||'')+'</p>'+(r.compatibilidad?'<div class="ia-am-compat">Compatibilidad: '+escapeHtmlRec(r.compatibilidad)+'</div>':'')+'<button type="button" class="ia-am-add" data-rec="'+i+'">+ Agregar a cotización</button></article>';});
        html+='</section>';
        const prods=Array.isArray(d.productos_aftermarket)?d.productos_aftermarket:[];
        html+='<section class="ia-am-section"><div class="ia-am-section-title">Aftermarket que suelen buscar estos propietarios</div>';
        if(!prods.length) html+='<div class="ia-am-muted">No se encontraron productos externos suficientemente claros.</div>';
        else prods.forEach(p=>{html+='<article class="ia-am-card aftermarket"><div class="ia-am-cardtop"><div><b>'+escapeHtmlRec(p.nombre||'Producto aftermarket')+'</b><div>'+iaAftermarketBadge(p.fuente||'Tendencia','purple')+'</div></div></div><p>'+escapeHtmlRec(p.motivo||'')+'</p>'+(p.compatibilidad?'<div class="ia-am-compat">Verificar: '+escapeHtmlRec(p.compatibilidad)+'</div>':'')+'<div class="ia-am-buy">'+iaAftermarketLink(p.links?.mercadolibre,'Mercado Libre','ml')+iaAftermarketLink(p.links?.amazon,'Amazon MX','amazon')+iaAftermarketLink(p.links?.google,'Buscar web','web')+'</div></article>';});
        html+='</section>';
        const web=Array.isArray(d.web_resultados)?d.web_resultados:[];
        if(web.length){html+='<section class="ia-am-section"><div class="ia-am-section-title">Investigación web</div><div class="ia-am-web">';web.slice(0,6).forEach(w=>{html+='<a href="'+escapeHtmlRec(w.url||'#')+'" target="_blank" rel="noopener noreferrer"><b>'+escapeHtmlRec(w.titulo||'Fuente')+'</b><span>'+escapeHtmlRec(w.snippet||'')+'</span></a>';});html+='</div><div class="ia-am-muted" style="margin-top:8px">La búsqueda externa usa únicamente el vehículo; no se envían nombres, teléfonos ni datos del cliente.</div></section>';}
        body.innerHTML=html;
        body.querySelectorAll('.ia-am-add').forEach(btn=>btn.addEventListener('click',()=>{const r=recs[Number(btn.dataset.rec||0)];if(r?.servicio){agregarFila(r.servicio);btn.textContent='✓ Agregado';btn.disabled=true;}}));
    }catch(e){body.innerHTML='<div class="ia-am-empty"><b>No se pudo completar la investigación.</b><br>'+escapeHtmlRec(e.message||String(e))+'<br><button type="button" class="ia-am-retry" onclick="investigarAftermarket()">Reintentar</button></div>';}
}

let iaPrecioTimer=null, iaPrecioFilaActiva=null, iaPrecioUltimaClave='', iaPrecioUltimoResultado=null, iaPrecioToastTimer=null;
let iaPrecioAbort=null, iaPrecioSolicitud=0;
function iaMoney(v){return Number(v||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',minimumFractionDigits:2,maximumFractionDigits:2});}
function iaPrecioAutoActivo(){const el=document.getElementById('ia-price-auto');return el?!!el.checked:(localStorage.getItem('srnu_ia_precio_auto')!=='0');}
function iaPrecioClasificacionClase(c){if(c==='competitivo')return 'good';if(c==='bajo'||c==='muy_bajo')return 'low';if(c==='alto'||c==='muy_alto')return 'high';return 'neutral';}
function iaPrecioClasificacionTexto(c){return ({muy_bajo:'MUY BAJO',bajo:'BAJO',competitivo:'COMPETITIVO',alto:'ALTO',muy_alto:'MUY ALTO',sin_datos:'SIN DATOS'})[c]||String(c||'SIN DATOS').toUpperCase();}
function iaPrecioEncontrarFila(origen=null){
    if(origen?.closest){const tr=origen.closest('#tabla-conceptos tr');if(tr&&tr.querySelector('input[name="concepto[]"]'))return tr;}
    if(iaPrecioFilaActiva&&document.body.contains(iaPrecioFilaActiva))return iaPrecioFilaActiva;
    return Array.from(document.querySelectorAll('#tabla-conceptos tr')).find(tr=>parseFloat(tr.querySelector('input[name="precio[]"]')?.value||0)>0&&String(tr.querySelector('input[name="concepto[]"]')?.value||'').trim())||null;
}
function iaPrecioMostrarToast(d){
    const t=document.getElementById('ia-price-toast'),tt=document.getElementById('ia-price-toast-title'),tx=document.getElementById('ia-price-toast-text');if(!t||!tt||!tx)return;
    const a=d?.analisis||{};tt.textContent='Precio '+iaPrecioClasificacionTexto(a.clasificacion||'sin_datos').toLowerCase();tx.textContent=(a.comentario||'')+(Number(a.precio_objetivo||0)>0?' · Objetivo '+iaMoney(a.precio_objetivo):'');t.classList.add('show');clearTimeout(iaPrecioToastTimer);iaPrecioToastTimer=setTimeout(()=>t.classList.remove('show'),6500);
}
function iaPrecioRender(d,fila){
    iaPrecioUltimoResultado=d;actualizarResumenCompactoPrecio(d);const body=document.getElementById('ia-price-live-body'),title=document.getElementById('ia-price-live-title');if(!body)return;
    const a=d.analisis||{},c=String(a.clasificacion||'sin_datos'),hist=d.historico||{},web=d.web||{},cat=d.catalogo||null;
    if(title)title.textContent=(fila?.querySelector('input[name="concepto[]"]')?.value||'Concepto').trim();
    const reasons=Array.isArray(a.razones)?a.razones:[];const alts=Array.isArray(d.alternativas)?d.alternativas:[];
    let html='<div class="ia-price-verdict"><div><span style="font-size:9px;color:#93c5fd;font-weight:900">'+escapeHtmlRec(d.motor||'DATOS')+'</span><h3>'+escapeHtmlRec(a.accion==='subir'?'Conviene subir':(a.accion==='bajar'?'Conviene revisar/bajar':(a.accion==='mantener'?'Buen precio':'Revisar precio')))+'</h3><p>'+escapeHtmlRec(a.comentario||'')+'</p></div><span class="ia-price-pill '+iaPrecioClasificacionClase(c)+'">'+escapeHtmlRec(iaPrecioClasificacionTexto(c))+'</span></div>';
    html+='<div class="ia-price-grid"><div><span>Rango sugerido</span><b>'+iaMoney(a.rango_min)+' – '+iaMoney(a.rango_max)+'</b></div><div><span>Objetivo</span><b>'+iaMoney(a.precio_objetivo)+'</b></div><div><span>Confianza</span><b>'+escapeHtmlRec(String(a.confianza||'baja').toUpperCase())+'</b></div>';
    if(Number(hist.n||0)>0)html+='<div><span>Histórico SRNU</span><b>'+iaMoney(hist.mediana)+' · '+Number(hist.n||0)+' reg.</b></div>';
    if(cat)html+='<div><span>Catálogo SRNU</span><b>'+iaMoney(cat.precio_base)+(cat.precio_fijo?' · FIJO':'')+'</b></div>';
    if(d.margen_bruto!==null&&d.margen_bruto!==undefined)html+='<div><span>Margen bruto aprox.</span><b>'+Number(d.margen_bruto).toFixed(1)+'%</b></div>';
    html+='</div>';
    if(reasons.length)html+='<ul class="ia-price-reasons">'+reasons.slice(0,5).map(x=>'<li>'+escapeHtmlRec(x)+'</li>').join('')+'</ul>';
    if(alts.length){html+='<div style="margin-top:9px;font-size:10px;color:#cbd5e1"><b>Opciones cercanas del catálogo:</b> '+alts.map(x=>escapeHtmlRec(x.nombre)+' ('+iaMoney(x.precio_base)+')').join(' · ')+'</div>';}
    html+='<div class="ia-price-actions">';if(Number(a.precio_objetivo||0)>0)html+='<button type="button" class="ia-price-use" onclick="iaPrecioUsarSugerido()">Usar '+iaMoney(a.precio_objetivo)+'</button>';html+='<button type="button" class="ia-price-refresh" onclick="iaPrecioAnalizar(true)">Consultar IA y web</button></div>';
    if(a.advertencia)html+='<div class="ia-price-warning">'+escapeHtmlRec(a.advertencia)+'</div>';
    if(Number(web.n||0)>0)html+='<div class="ia-price-warning">Se consultaron '+Number(web.n||0)+' resultados web. Las cifras externas solo pesan cuando parecen comparables con el servicio completo.</div>';
    body.innerHTML=html;iaPrecioMostrarToast(d);
}
async function iaPrecioAnalizar(forzar=false,origen=null){
    if(!iaPrecioAutoActivo()&&!forzar)return;const fila=iaPrecioEncontrarFila(origen);if(!fila)return;iaPrecioFilaActiva=fila;
    const concepto=(fila.querySelector('input[name="concepto[]"]')?.value||'').trim(),precio=parseFloat(fila.querySelector('input[name="precio[]"]')?.value||0),costo=parseFloat(fila.querySelector('input[name="costo_interno[]"]')?.value||0),catalogoId=parseInt(fila.querySelector('input[name="catalogo_id[]"]')?.value||0,10)||0,vehiculo=(document.getElementById('vehiculo-input')?.value||'').trim();
    if(!concepto||!Number.isFinite(precio)||precio<=0){iaPrecioAbort?.abort();iaPrecioSolicitud++;iaPrecioUltimaClave='';return;}
    const clave=[vehiculo,concepto,precio,costo,catalogoId].join('|');if(!forzar&&clave===iaPrecioUltimaClave)return;iaPrecioUltimaClave=clave;
    iaPrecioAbort?.abort();
    const controlador=new AbortController(),solicitud=++iaPrecioSolicitud;iaPrecioAbort=controlador;
    const body=document.getElementById('ia-price-live-body'),title=document.getElementById('ia-price-live-title'),compact=document.getElementById('ia-price-compact');if(title)title.textContent=concepto;if(compact){compact.textContent='Analizando '+iaMoney(precio)+'…';compact.className='ia-price-compact';}if(body)body.innerHTML='<div class="ia-price-loading">Analizando '+escapeHtmlRec(concepto)+' a '+iaMoney(precio)+'…</div>';
    try{
        const fd=new FormData();fd.append('vehiculo',vehiculo);fd.append('concepto',concepto);fd.append('precio',String(precio));fd.append('costo',String(costo||0));fd.append('catalogo_id',String(catalogoId));fd.append('profundo',forzar?'1':'0');
        const res=await fetch('asesor_precios.php',{method:'POST',body:fd,signal:controlador.signal});const d=await res.json();
        if(solicitud!==iaPrecioSolicitud||!document.body.contains(fila))return;
        const vigente=[(document.getElementById('vehiculo-input')?.value||'').trim(),(fila.querySelector('input[name="concepto[]"]')?.value||'').trim(),parseFloat(fila.querySelector('input[name="precio[]"]')?.value||0),parseFloat(fila.querySelector('input[name="costo_interno[]"]')?.value||0),parseInt(fila.querySelector('input[name="catalogo_id[]"]')?.value||0,10)||0].join('|');
        if(vigente!==clave)return;
        if(!d.ok)throw new Error(d.error||'No fue posible evaluar el precio');iaPrecioRender(d,fila);
    }catch(e){
        if(e.name==='AbortError'||solicitud!==iaPrecioSolicitud)return;
        iaPrecioUltimaClave='';if(body)body.innerHTML='<div class="ia-price-placeholder">No pude evaluar este precio ahora: '+escapeHtmlRec(e.message||String(e))+'</div>';
    }finally{if(iaPrecioAbort===controlador)iaPrecioAbort=null;}
}
function iaPrecioProgramar(origen=null){
    if(origen?.closest){const tr=origen.closest('#tabla-conceptos tr');if(tr)iaPrecioFilaActiva=tr;}clearTimeout(iaPrecioTimer);iaPrecioTimer=setTimeout(()=>iaPrecioAnalizar(false,origen),1100);
}
function iaPrecioUsarSugerido(){const a=iaPrecioUltimoResultado?.analisis||{},v=Number(a.precio_objetivo||0);if(!v||!iaPrecioFilaActiva)return;const inp=iaPrecioFilaActiva.querySelector('input[name="precio[]"]');if(!inp)return;inp.value=v.toFixed(2);inp.dispatchEvent(new Event('input',{bubbles:true}));inp.dispatchEvent(new Event('change',{bubbles:true}));}
document.addEventListener('focusin',e=>{if(e.target.matches('#tabla-conceptos input[name="concepto[]"],#tabla-conceptos input[name="precio[]"],#tabla-conceptos input[name="costo_interno[]"]')){iaPrecioFilaActiva=e.target.closest('tr');iaPrecioProgramar(e.target);}});
document.addEventListener('input',e=>{if(e.target.matches('#tabla-conceptos input[name="concepto[]"],#tabla-conceptos input[name="precio[]"],#tabla-conceptos input[name="costo_interno[]"],#vehiculo-input'))iaPrecioProgramar(e.target);});
document.addEventListener('change',e=>{if(e.target.matches('#tabla-conceptos input[name="precio[]"],#tabla-conceptos input[name="catalogo_id[]"],#catalogo-servicio-select'))iaPrecioProgramar(e.target);});
document.addEventListener('DOMContentLoaded',()=>{aplicarEstadoAsesorPrecio();actualizarResumenCompactoPrecio();const sw=document.getElementById('ia-price-auto');if(sw){sw.checked=localStorage.getItem('srnu_ia_precio_auto')!=='0';sw.addEventListener('change',()=>{localStorage.setItem('srnu_ia_precio_auto',sw.checked?'1':'0');if(sw.checked)iaPrecioProgramar();});}setTimeout(()=>iaPrecioProgramar(),1400);});

