function agregarDesdeCatalogo() {
    const select = document.getElementById('catalogo-servicio-select');
    const script = document.getElementById('catalogo-servicios-json');
    if (!select || !script || !select.value) return;
    let catalogo = [];
    try { catalogo = JSON.parse(script.textContent || '[]'); } catch(e) { return; }
    const servicio = catalogo.find(x => String(x.id) === String(select.value));
    if (servicio) agregarFila(servicio);
}

function quitarFila(boton) {

    const tabla =
        document.getElementById(
            'tabla-conceptos'
        );


    /*
     * Dejar al menos una fila
     */

    if (tabla.rows.length > 2) {

        boton
            .closest('tr')
            .remove();
        if (typeof window.actualizarResumenInterno === 'function') window.actualizarResumenInterno();
        if (typeof window.srnuActualizarMSI === 'function') window.srnuActualizarMSI();

    }

}

