function generarPDFServidor(tipo) {
    const bbvaPyme = <?= $bbva_pyme ? 'true' : 'false' ?>;
    if (bbvaPyme) tipo = 'factura';
    const id = <?= (int)$cotizacion_id ?>;
    if (!id) {
        imprimirCotizacion(tipo);
        return;
    }
    window.location.href = 'preview.php?id=' + encodeURIComponent(id) + '&tipo=' + encodeURIComponent(tipo);
}

function imprimirCotizacion(tipo) {


    const conFactura =
        tipo === 'factura';


    /* ======================================================
       MSI
       ====================================================== */

    const msiFactura =
        document.getElementById(
            'msi-factura'
        );


    const msiSinFactura =
        document.getElementById(
            'msi-sin-factura'
        );


    const msiSeccion =
        document.getElementById(
            'msi-seccion'
        );

    const msiDisponibleParaImpresion =
        conFactura
            ? <?= ($tarjeta_una_exhibicion_factura !== null || !empty($msi_opciones_factura) || !empty($msi_no_disponible_factura)) ? 'true' : 'false' ?>
            : <?= ($tarjeta_una_exhibicion_sin_factura !== null || !empty($msi_opciones_sin_factura) || !empty($msi_no_disponible_sin_factura)) ? 'true' : 'false' ?>;

    if (msiSeccion) {
        msiSeccion.style.display =
            msiDisponibleParaImpresion ? '' : 'none';
    }

    if (msiFactura) {

        msiFactura.style.display =
            conFactura
                ? ''
                : 'none';

    }


    if (msiSinFactura) {

        msiSinFactura.style.display =
            conFactura
                ? 'none'
                : '';

    }


    /* ======================================================
       TOTALES HOJA 1
       ====================================================== */

    const filas =
        document.querySelectorAll(
            '.totales .fila'
        );


    if (filas.length >= 3) {


        const ivaSpan =
            filas[1]
            .querySelector(
                'span:last-child'
            );


        const totalSpan =
            filas[2]
            .querySelector(
                'span:last-child'
            );


        if (ivaSpan) {

            ivaSpan.textContent =
                conFactura

                    ? '$<?= number_format(
                        $total_con_factura
                        - $subtotal,
                        2
                    ) ?>'

                    : '$0.00';

        }


        if (totalSpan) {

            totalSpan.textContent =
                conFactura

                    ? '$<?= number_format(
                        $total_con_factura,
                        2
                    ) ?>'

                    : '$<?= number_format(
                        $total_sin_factura,
                        2
                    ) ?>';

        }

    }


    /* ======================================================
       ANTICIPO PERSONALIZADO
       ====================================================== */

    const pagoTotal =
        document.getElementById(
            'pago-total'
        );


    const anticipoMonto =
        document.getElementById(
            'anticipo-monto'
        );


    const saldoMonto =
        document.getElementById(
            'saldo-monto'
        );

    const anticipoPorcentaje = document.getElementById('anticipo-porcentaje');
    const saldoPorcentaje = document.getElementById('saldo-porcentaje');


    if (conFactura) {


        if (pagoTotal) {

            pagoTotal.textContent =
                '$<?= number_format(
                    $total_con_factura,
                    2
                ) ?>';

        }


        if (anticipoMonto) {

            anticipoMonto.textContent =
                '$<?= number_format(
                    $anticipo_factura['monto'],
                    2
                ) ?>';

        }


        if (saldoMonto) {

            saldoMonto.textContent =
                '$<?= number_format(
                    $anticipo_factura['saldo'],
                    2
                ) ?>';

        }
        if (anticipoPorcentaje) anticipoPorcentaje.textContent = <?= json_encode(rtrim(rtrim(number_format($anticipo_factura['porcentaje'], 2, '.', ''), '0'), '.') . '%') ?>;
        if (saldoPorcentaje) saldoPorcentaje.textContent = <?= json_encode(rtrim(rtrim(number_format($anticipo_factura['saldo_porcentaje'], 2, '.', ''), '0'), '.') . '%') ?>;

    } else {


        if (pagoTotal) {

            pagoTotal.textContent =
                '$<?= number_format(
                    $total_sin_factura,
                    2
                ) ?>';

        }


        if (anticipoMonto) {

            anticipoMonto.textContent =
                '$<?= number_format(
                    $anticipo_sin_factura['monto'],
                    2
                ) ?>';

        }


        if (saldoMonto) {

            saldoMonto.textContent =
                '$<?= number_format(
