        }
        if (anticipoPorcentaje) anticipoPorcentaje.textContent = <?= json_encode(rtrim(rtrim(number_format($anticipo_sin_factura['porcentaje'], 2, '.', ''), '0'), '.') . '%') ?>;
        if (saldoPorcentaje) saldoPorcentaje.textContent = <?= json_encode(rtrim(rtrim(number_format($anticipo_sin_factura['saldo_porcentaje'], 2, '.', ''), '0'), '.') . '%') ?>;

    }


    /* ======================================================
       ESPERAR A QUE EL NAVEGADOR ACTUALICE EL DOM
       ====================================================== */

    requestAnimationFrame(() => {

        requestAnimationFrame(() => {

            window.print();

        });

    });

}


/* ==========================================================
   RESTAURAR ESTADO DESPUES DE IMPRIMIR
   ========================================================== */

window.addEventListener(
    'afterprint',
    function() {


        const msiFactura =
            document.getElementById(
                'msi-factura'
            );


        const msiSinFactura =
            document.getElementById(
                'msi-sin-factura'
            );

        const msiSeccion =
            document.getElementById(
                'msi-seccion'
            );

        if (msiSeccion) {
            msiSeccion.style.display = '';
        }


        if (msiFactura) {

            msiFactura.style.display = '';

        }


        if (msiSinFactura) {

            msiSinFactura.style.display =
                'none';

        }


    }
);

</script>

